192→// collectTraceEntries reads a JSONL log file and returns the last N trace entries,
193→// ordered newest first. If hookFilter is non-empty, only entries with a matching
194→// Op field are included.
195→func collectTraceEntries(logFile string, last int, hookFilter string) ([]traceEntry, error) {
196→	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
197→	if err != nil {
198→		if errors.Is(err, os.ErrNotExist) {
199→			return nil, nil
200→		}
201→		return nil, fmt.Errorf("opening log file: %w", err)
202→	}
203→	defer f.Close()
204→
205→	var entries []traceEntry
206→
207→	scanner := bufio.NewScanner(f)
208→	scanner.Buffer(make([]byte, 0, bufio.MaxScanTokenSize), 1024*1024) // allow up to 1MB lines in shared log file
209→	for scanner.Scan() {
210→		entry := parseTraceEntry(scanner.Text())
211→		if entry == nil {
212→			continue
213→		}
214→		if hookFilter != "" && entry.Op != hookFilter {
215→			continue
216→		}
217→		entries = append(entries, *entry)
218→	}
219→
220→	if err := scanner.Err(); err != nil {
221→		return nil, fmt.Errorf("reading log file: %w", err)
222→	}
223→
224→	// Take the last N entries
225→	if len(entries) > last {
226→		entries = entries[len(entries)-last:]
227→	}
228→
229→	// Reverse so newest entries are first
230→	slices.Reverse(entries)
231→
232→	return entries, nil
233→}
234→
235→// renderTraceEntries writes a formatted table of trace entries to w.
236→// If entries is empty, it prints a help message about enabling traces.
237→func renderTraceEntries(w io.Writer, entries []traceEntry) {
238→	if len(entries) == 0 {
239→		fmt.Fprintln(w, "No trace entries found.")
240→		fmt.Fprintln(w, `Traces are logged at DEBUG level. Make sure ENTIRE_LOG_LEVEL=DEBUG is set`)
241→		fmt.Fprintln(w, `in your shell profile, or set log_level to "DEBUG" in .entire/settings.json.`)
242→		return
243→	}
244→
245→	for i, entry := range entries {
246→		if i > 0 {
247→			fmt.Fprintln(w)
248→		}
249→
250→		// Header line: op  duration  [timestamp]
251→		header := fmt.Sprintf("%s  %dms", entry.Op, entry.DurationMs)
252→		if !entry.Time.IsZero() {
253→			header += "  " + entry.Time.Format(time.RFC3339)
254→		}
255→		fmt.Fprintln(w, header)
256→		fmt.Fprintln(w)
257→
258→		if len(entry.Steps) == 0 {
259→			continue
260→		}
261→
262→		// Compute max name display width (at least len("STEP")).
263→		// Sub-steps are indented 5 extra display columns relative to parent rows
264→		// ("    " + "├─ " = 7 display cols vs "  " = 2 display cols).
265→		const subExtraIndent = 5
266→		nameWidth := len("STEP")
267→		for _, s := range entry.Steps {
268→			if len(s.Name) > nameWidth {
269→				nameWidth = len(s.Name)
270→			}
271→			for _, sub := range s.SubSteps {
272→				if needed := len(sub.Name) + subExtraIndent; needed > nameWidth {
273→					nameWidth = needed
274→				}
275→			}
276→		}
277→
278→		// Column header
279→		fmt.Fprintf(w, "  %-*s  %8s\n", nameWidth, "STEP", "DURATION")
280→
281→		// Step rows
282→		for _, s := range entry.Steps {
283→			dur := fmt.Sprintf("%dms", s.DurationMs)
284→			line := fmt.Sprintf("  %-*s  %8s", nameWidth, s.Name, dur)
285→			if s.Error {
286→				line += "  x"
287→			}
288→			fmt.Fprintln(w, line)
289→
290→			// Sub-step rows with ASCII tree connectors.
291→			// Pad manually to avoid multi-byte UTF-8 box-drawing chars
292→			// (├─, └─) breaking Go's byte-based %-*s alignment.
293→			for i, sub := range s.SubSteps {
294→				connector := "├─"
295→				if i == len(s.SubSteps)-1 {
296→					connector = "└─"
297→				}
298→				subDur := fmt.Sprintf("%dms", sub.DurationMs)
299→				pad := nameWidth - subExtraIndent - len(sub.Name)
300→				if pad < 0 {
301→					pad = 0
302→				}
303→				subLine := fmt.Sprintf("    %s %s%s  %8s", connector, sub.Name, strings.Repeat(" ", pad), subDur)
304→				if sub.Error {
305→					subLine += "  x"
306→				}
307→				fmt.Fprintln(w, subLine)
308→			}
309→		}
310→	}
311→}
