1199→// runExplainCommit looks up the checkpoint associated with a commit.
1200→// Extracts the Entire-Checkpoint trailer and delegates to checkpoint detail view.
1201→// If no trailer found, shows a message indicating no associated checkpoint.
1202→func runExplainCommit(ctx context.Context, w io.Writer, commitRef string, noPager, verbose, full, searchAll bool) error {
1203→	repo, err := openRepository(ctx)
1204→	if err != nil {
1205→		return fmt.Errorf("not a git repository: %w", err)
1206→	}
1207→
1208→	// Resolve the commit reference
1209→	hash, err := repo.ResolveRevision(plumbing.Revision(commitRef))
1210→	if err != nil {
1211→		return fmt.Errorf("commit not found: %s", commitRef)
1212→	}
1213→
1214→	commit, err := repo.CommitObject(*hash)
1215→	if err != nil {
1216→		return fmt.Errorf("failed to get commit: %w", err)
1217→	}
1218→
1219→	// Extract Entire-Checkpoint trailer
1220→	checkpointID, hasCheckpoint := trailers.ParseCheckpoint(commit.Message)
1221→	if !hasCheckpoint {
1222→		fmt.Fprintln(w, "No associated Entire checkpoint")
1223→		fmt.Fprintf(w, "\nCommit %s does not have an Entire-Checkpoint trailer.\n", hash.String()[:7])
1224→		fmt.Fprintln(w, "This commit was not created during an Entire session, or the trailer was removed.")
1225→		return nil
1226→	}
1227→
1228→	// Delegate to checkpoint detail view
1229→	// Note: errW is only used for generate mode, but we pass w for safety
1230→	return runExplainCheckpoint(ctx, w, w, checkpointID.String(), noPager, verbose, full, false, false, false, searchAll)
1231→}
