1247→	}
1248→
1249→	fmt.Fprintf(&sb, "Checkpoints: %d\n", len(checkpoints))
1250→
1251→	// Checkpoint details
1252→	for _, cp := range checkpoints {
1253→		sb.WriteString("\n")
1254→
1255→		// Checkpoint header
1256→		taskMarker := ""
1257→		if cp.IsTaskCheckpoint {
