1259→		}
1260→		fmt.Fprintf(&sb, "─── Checkpoint %d [%s] %s%s ───\n",
1261→			cp.Index, cp.ShortID, cp.Timestamp.Format("2006-01-02 15:04"), taskMarker)
1262→		sb.WriteString("\n")
1263→
1264→		// Display all interactions in this checkpoint
1265→		for i, inter := range cp.Interactions {
1266→			// For multiple interactions, add a sub-header
1267→			if len(cp.Interactions) > 1 {
1268→				fmt.Fprintf(&sb, "### Interaction %d\n\n", i+1)
1269→			}
1270→
1271→			// Prompt section
1272→			if inter.Prompt != "" {
1273→				sb.WriteString("## Prompt\n\n")
1274→				sb.WriteString(inter.Prompt)
1275→				sb.WriteString("\n\n")
1276→			}
1277→
1278→			// Response section
1279→			if len(inter.Responses) > 0 {
1280→				sb.WriteString("## Responses\n\n")
1281→				sb.WriteString(strings.Join(inter.Responses, "\n\n"))
1282→				sb.WriteString("\n\n")
1283→			}
1284→
1285→			// Files modified for this interaction
1286→			if len(inter.Files) > 0 {
1287→				fmt.Fprintf(&sb, "Files Modified (%d):\n", len(inter.Files))
1288→				for _, file := range inter.Files {
1289→					fmt.Fprintf(&sb, "  - %s\n", file)
1290→				}
1291→				sb.WriteString("\n")
1292→			}
1293→		}
1294→
1295→		// If no interactions, show message and/or files
1296→		if len(cp.Interactions) == 0 {
1297→			// Show commit message as summary when no transcript available
1298→			if cp.Message != "" {
1299→				sb.WriteString(cp.Message)
1300→				sb.WriteString("\n\n")
1301→			}
1302→			// Show aggregate files if available
1303→			if len(cp.Files) > 0 {
1304→				fmt.Fprintf(&sb, "Files Modified (%d):\n", len(cp.Files))
1305→				for _, file := range cp.Files {
1306→					fmt.Fprintf(&sb, "  - %s\n", file)
1307→				}
1308→			}
1309→		}
1310→	}
1311→
1312→	return sb.String()
1313→}
