1315→// outputWithPager outputs content through a pager if stdout is a terminal and content is long.
1316→func outputWithPager(w io.Writer, content string) {
1317→	// Check if we're writing to stdout and it's a terminal
1318→	//nolint:gosec // G115: uintptr->int is safe for fd on 64-bit platforms
1319→	if f, ok := w.(*os.File); ok && f == os.Stdout && term.IsTerminal(int(f.Fd())) {
1320→		// Get terminal height
1321→		_, height, err := term.GetSize(int(f.Fd())) //nolint:gosec // G115: same as above
1322→		if err != nil {
1323→			height = 24 // Default fallback
1324→		}
1325→
1326→		// Count lines in content
1327→		lineCount := strings.Count(content, "\n")
1328→
1329→		// Use pager if content exceeds terminal height
1330→		if lineCount > height-2 {
1331→			pager := os.Getenv("PAGER")
1332→			if pager == "" {
1333→				pager = "less"
1334→			}
1335→
1336→			// Use context.Background() intentionally — pagers are interactive
1337→			// processes that handle signals (including SIGINT) themselves.
1338→			// Using the cancellable ctx would cause exec.CommandContext to
1339→			// SIGKILL the pager on Ctrl+C, preventing it from restoring
1340→			// terminal state (raw mode, echo, etc.).
1341→			cmd := exec.CommandContext(context.Background(), pager)
1342→			cmd.Stdin = strings.NewReader(content)
1343→			cmd.Stdout = f
1344→			cmd.Stderr = os.Stderr
1345→
1346→			if err := cmd.Run(); err != nil {
1347→				// Fallback to direct output if pager fails
1348→				fmt.Fprint(w, content)
1349→			}
1350→			return
1351→		}
1352→	}
1353→
1354→	// Direct output for non-terminal or short content
1355→	fmt.Fprint(w, content)
1356→}
