101→
102→	// ToolDetail is a description or file path (for tool entries)
103→	ToolDetail string
104→}
105→
106→// minimalDetailTools lists tools that should show only essential details in summaries.
107→// These tools often have verbose outputs that don't add value to summarization.
108→// The detail shown is typically just a path, URL, or identifier rather than full content.
109→var minimalDetailTools = map[string]bool{
110→	"Skill":    true, // Show skill name only, not loaded content
111→	"Read":     true, // Show file path only, not file contents
112→	"WebFetch": true, // Show URL only, not fetched content
113→}
114→
115→// BuildCondensedTranscriptFromBytes parses transcript bytes and extracts a condensed view.
116→// This is a convenience function that combines parsing and condensing.
117→// The agentType parameter determines which parser to use (Claude/OpenCode JSONL vs Gemini JSON).
118→func BuildCondensedTranscriptFromBytes(content []byte, agentType types.AgentType) ([]Entry, error) {
119→	switch agentType {
120→	case agent.AgentTypeGemini:
121→		return buildCondensedTranscriptFromGemini(content)
122→	case agent.AgentTypeFactoryAIDroid:
123→		return buildCondensedTranscriptFromDroid(content)
124→	case agent.AgentTypeOpenCode:
125→		return buildCondensedTranscriptFromOpenCode(content)
126→	case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeUnknown:
127→		// Claude/cursor format - fall through to shared logic below
128→	}
129→	// Claude format (JSONL) - handles Claude Code, Unknown, and any future agent types
130→	lines, err := transcript.ParseFromBytes(content)
131→	if err != nil {
132→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
133→	}
134→	return BuildCondensedTranscript(lines), nil
135→}
136→
137→// buildCondensedTranscriptFromGemini parses Gemini JSON transcript and extracts a condensed view.
138→func buildCondensedTranscriptFromGemini(content []byte) ([]Entry, error) {
139→	geminiTranscript, err := geminicli.ParseTranscript(content)
140→	if err != nil {
141→		return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
142→	}
143→
144→	var entries []Entry
145→	for _, msg := range geminiTranscript.Messages {
146→		switch msg.Type {
147→		case geminicli.MessageTypeUser:
148→			if msg.Content != "" {
149→				entries = append(entries, Entry{
150→					Type:    EntryTypeUser,
151→					Content: msg.Content,
152→				})
153→			}
154→		case geminicli.MessageTypeGemini:
155→			// Add assistant content
156→			if msg.Content != "" {
157→				entries = append(entries, Entry{
158→					Type:    EntryTypeAssistant,
159→					Content: msg.Content,
160→				})
161→			}
162→			// Add tool calls
163→			for _, tc := range msg.ToolCalls {
164→				entries = append(entries, Entry{
165→					Type:       EntryTypeTool,
166→					ToolName:   tc.Name,
167→					ToolDetail: extractGenericToolDetail(tc.Args),
168→				})
169→			}
170→		}
171→	}
172→
173→	return entries, nil
174→}
175→
176→// buildCondensedTranscriptFromOpenCode parses OpenCode export JSON transcript and extracts a condensed view.
177→func buildCondensedTranscriptFromOpenCode(content []byte) ([]Entry, error) {
178→	session, err := opencode.ParseExportSession(content)
179→	if err != nil {
180→		return nil, fmt.Errorf("failed to parse OpenCode transcript: %w", err)
181→	}
182→	if session == nil {
183→		return nil, nil
184→	}
185→
186→	var entries []Entry
187→	for _, msg := range session.Messages {
188→		switch msg.Info.Role {
189→		case "user":
190→			text := opencode.ExtractTextFromParts(msg.Parts)
191→			if text != "" {
192→				entries = append(entries, Entry{
193→					Type:    EntryTypeUser,
194→					Content: text,
195→				})
196→			}
197→		case "assistant":
198→			text := opencode.ExtractTextFromParts(msg.Parts)
199→			if text != "" {
200→				entries = append(entries, Entry{
201→					Type:    EntryTypeAssistant,
202→					Content: text,
203→				})
204→			}
205→			for _, part := range msg.Parts {
206→				if part.Type == "tool" && part.State != nil {
207→					entries = append(entries, Entry{
208→						Type:       EntryTypeTool,
209→						ToolName:   part.Tool,
210→						ToolDetail: extractOpenCodeToolDetail(part.State.Input),
211→					})
212→				}
213→			}
214→		}
215→	}
216→
217→	return entries, nil
218→}
219→
220→// buildCondensedTranscriptFromDroid parses Droid transcript and extracts a condensed view.
221→func buildCondensedTranscriptFromDroid(content []byte) ([]Entry, error) {
222→	droidLines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes(content, 0)
223→	if err != nil {
224→		return nil, fmt.Errorf("failed to parse Droid transcript: %w", err)
225→	}
226→	return BuildCondensedTranscript(droidLines), nil
227→}
