312→// generateCheckpointSummary generates an AI summary for a checkpoint and persists it.
313→// The summary is generated from the scoped transcript (only this checkpoint's portion),
314→// not the entire session transcript.
315→func generateCheckpointSummary(ctx context.Context, w, _ io.Writer, store *checkpoint.GitStore, checkpointID id.CheckpointID, cpSummary *checkpoint.CheckpointSummary, content *checkpoint.SessionContent, force bool) error {
316→	// Check if summary already exists
317→	if content.Metadata.Summary != nil && !force {
318→		return fmt.Errorf("checkpoint %s already has a summary (use --force to regenerate)", checkpointID)
319→	}
320→
321→	// Check if transcript exists
322→	if len(content.Transcript) == 0 {
323→		return fmt.Errorf("checkpoint %s has no transcript to summarize", checkpointID)
324→	}
325→
326→	// Scope the transcript to only this checkpoint's portion
327→	scopedTranscript := scopeTranscriptForCheckpoint(content.Transcript, content.Metadata.GetTranscriptStart(), content.Metadata.Agent)
328→	if len(scopedTranscript) == 0 {
329→		return fmt.Errorf("checkpoint %s has no transcript content for this checkpoint (scoped)", checkpointID)
330→	}
331→
332→	// Generate summary using shared helper
333→	logging.Info(ctx, "generating checkpoint summary")
334→
335→	summary, err := summarize.GenerateFromTranscript(ctx, scopedTranscript, cpSummary.FilesTouched, content.Metadata.Agent, nil)
336→	if err != nil {
337→		return fmt.Errorf("failed to generate summary: %w", err)
338→	}
339→
340→	// Persist the summary
341→	if err := store.UpdateSummary(ctx, checkpointID, summary); err != nil {
342→		return fmt.Errorf("failed to save summary: %w", err)
343→	}
344→
345→	fmt.Fprintln(w, "✓ Summary generated and saved")
346→	return nil
347→}
