349→// explainTemporaryCheckpoint finds and formats a temporary checkpoint by shadow commit hash prefix.
350→// Returns the formatted output and whether the checkpoint was found.
351→// Searches ALL shadow branches, not just the one for current HEAD, to find checkpoints
352→// created from different base commits (e.g., if HEAD advanced since session start).
353→// The writer w is used for raw transcript output to bypass the pager.
354→func explainTemporaryCheckpoint(ctx context.Context, w io.Writer, repo *git.Repository, store *checkpoint.GitStore, shaPrefix string, verbose, full, rawTranscript bool) (string, bool) {
355→	// List temporary checkpoints from ALL shadow branches
356→	// This ensures we find checkpoints even if HEAD has advanced since the session started
357→	tempCheckpoints, err := store.ListAllTemporaryCheckpoints(ctx, "", branchCheckpointsLimit)
358→	if err != nil {
359→		return "", false
360→	}
361→
362→	// Find checkpoints matching the SHA prefix - check for ambiguity
363→	var matches []checkpoint.TemporaryCheckpointInfo
364→	for _, tc := range tempCheckpoints {
365→		if strings.HasPrefix(tc.CommitHash.String(), shaPrefix) {
366→			matches = append(matches, tc)
367→		}
368→	}
369→
370→	if len(matches) == 0 {
371→		return "", false
372→	}
373→
374→	if len(matches) > 1 {
375→		// Multiple matches - return ambiguous error (consistent with committed checkpoint behavior)
376→		var sb strings.Builder
377→		fmt.Fprintf(&sb, "ambiguous checkpoint prefix %q matches %d temporary checkpoints:\n", shaPrefix, len(matches))
378→		for _, m := range matches {
379→			shortID := m.CommitHash.String()[:7]
380→			fmt.Fprintf(&sb, "  %s  %s  session %s\n",
381→				shortID,
382→				m.Timestamp.Format("2006-01-02 15:04:05"),
383→				m.SessionID)
384→		}
385→		// Return as "not found" with error message - caller will use this as error
386→		return sb.String(), false
387→	}
388→
389→	tc := matches[0]
390→
391→	// Get shadow commit and tree to read metadata
392→	shadowCommit, commitErr := repo.CommitObject(tc.CommitHash)
393→	if commitErr != nil {
394→		return "", false
395→	}
396→
397→	shadowTree, treeErr := shadowCommit.Tree()
398→	if treeErr != nil {
399→		return "", false
400→	}
401→
402→	// Read agent type from shadow branch metadata (stored during checkpoint creation)
403→	agentType := strategy.ReadAgentTypeFromTree(shadowTree, tc.MetadataDir)
404→
405→	// Handle raw transcript output
406→	if rawTranscript {
407→		transcriptBytes, transcriptErr := store.GetTranscriptFromCommit(ctx, tc.CommitHash, tc.MetadataDir, agentType)
408→		if transcriptErr != nil || len(transcriptBytes) == 0 {
409→			// Return specific error message (consistent with committed checkpoints)
410→			return fmt.Sprintf("checkpoint %s has no transcript", tc.CommitHash.String()[:7]), false
411→		}
412→		// Write directly to writer (no pager, no formatting) - matches committed checkpoint behavior
413→		if _, writeErr := fmt.Fprint(w, string(transcriptBytes)); writeErr != nil {
414→			return fmt.Sprintf("failed to write transcript: %v", writeErr), false
415→		}
416→		return "", true
417→	}
418→
419→	// Read prompts from shadow branch
420→	sessionPrompt := strategy.ReadSessionPromptFromTree(shadowTree, tc.MetadataDir)
421→
422→	// Build output similar to formatCheckpointOutput but for temporary
423→	var sb strings.Builder
424→	shortID := tc.CommitHash.String()[:7]
425→	fmt.Fprintf(&sb, "Checkpoint: %s [temporary]\n", shortID)
426→	fmt.Fprintf(&sb, "Session: %s\n", tc.SessionID)
427→	fmt.Fprintf(&sb, "Created: %s\n", tc.Timestamp.Format("2006-01-02 15:04:05"))
428→	sb.WriteString("\n")
429→
430→	// Intent from prompt
431→	intent := "(not available)"
432→	if sessionPrompt != "" {
433→		lines := strings.Split(sessionPrompt, "\n")
434→		if len(lines) > 0 && lines[0] != "" {
435→			intent = strategy.TruncateDescription(lines[0], maxIntentDisplayLength)
436→		}
437→	}
438→	fmt.Fprintf(&sb, "Intent: %s\n", intent)
439→	sb.WriteString("Outcome: (not generated)\n")
440→
441→	// Transcript section: full shows entire session, verbose shows checkpoint scope
442→	// For temporary checkpoints, load transcript and compute scope from parent commit
443→	var fullTranscript []byte
444→	var scopedTranscript []byte
445→	if full || verbose {
446→		fullTranscript, _ = store.GetTranscriptFromCommit(ctx, tc.CommitHash, tc.MetadataDir, agentType) //nolint:errcheck // Best-effort
447→
448→		if verbose && len(fullTranscript) > 0 {
449→			// Compute scoped transcript by finding where parent's transcript ended
450→			// Each shadow branch commit has the full transcript up to that point,
451→			// so we diff against parent to get just this checkpoint's activity
452→			scopedTranscript = fullTranscript // Default to full if no parent
453→			if shadowCommit.NumParents() > 0 {
454→				if parent, parentErr := shadowCommit.Parent(0); parentErr == nil {
455→					parentTranscript, _ := store.GetTranscriptFromCommit(ctx, parent.Hash, tc.MetadataDir, agentType) //nolint:errcheck // Best-effort
456→					if len(parentTranscript) > 0 {
457→						parentOffset := transcriptOffset(parentTranscript, agentType)
458→						scopedTranscript = scopeTranscriptForCheckpoint(fullTranscript, parentOffset, agentType)
459→					}
460→				}
461→			}
462→		}
463→	}
464→	appendTranscriptSection(&sb, verbose, full, fullTranscript, scopedTranscript, sessionPrompt, agentType)
465→
466→	return sb.String(), true
467→}
