469→// getAssociatedCommits finds git commits that reference the given checkpoint ID.
470→// Searches commits on the current branch for Entire-Checkpoint trailer matches.
471→// When searchAll is true, uses full DAG walk with no depth limit (may be slow).
472→// This finds checkpoint commits on merged feature branches (second parents of merges).
473→func getAssociatedCommits(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, searchAll bool) ([]associatedCommit, error) {
474→	head, err := repo.Head()
475→	if err != nil {
476→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
477→	}
478→
479→	commits := []associatedCommit{} // Initialize as empty slice, not nil (nil means "not searched")
480→	targetID := checkpointID.String()
481→
482→	collectCommit := func(c *object.Commit) {
483→		fullSHA := c.Hash.String()
484→		shortSHA := fullSHA
485→		if len(fullSHA) >= 7 {
486→			shortSHA = fullSHA[:7]
487→		}
488→		commits = append(commits, associatedCommit{
489→			SHA:      fullSHA,
490→			ShortSHA: shortSHA,
491→			Message:  strings.Split(c.Message, "\n")[0],
492→			Author:   c.Author.Name,
493→			Email:    c.Author.Email,
494→			Date:     c.Author.When,
495→		})
496→	}
497→
498→	if searchAll {
499→		// Full DAG walk: follows all parents of merge commits, no depth limit.
500→		// This finds checkpoint commits on merged feature branches.
501→		iter, iterErr := repo.Log(&git.LogOptions{
502→			From:  head.Hash(),
503→			Order: git.LogOrderCommitterTime,
504→		})
505→		if iterErr != nil {
506→			return nil, fmt.Errorf("failed to get commit log: %w", iterErr)
507→		}
508→		defer iter.Close()
