package insights

import "math"

// Scoring weights for the composite score.
const (
	weightTokenEfficiency  = 0.30
	weightFirstPassSuccess = 0.30
	weightFriction         = 0.25
	weightFocus            = 0.15
)

// ScoreSession computes a composite quality score from raw session data.
func ScoreSession(raw RawSessionData) SessionScore {
	breakdown := ScoreBreakdown{
		TokenEfficiency:  scoreTokenEfficiency(raw),
		FirstPassSuccess: scoreFirstPass(raw),
		FrictionScore:    scoreFriction(raw),
		FocusScore:       scoreFocus(raw),
	}

	overall := breakdown.TokenEfficiency*weightTokenEfficiency +
		breakdown.FirstPassSuccess*weightFirstPassSuccess +
		breakdown.FrictionScore*weightFriction +
		breakdown.FocusScore*weightFocus

	return SessionScore{
		SessionID:     raw.SessionID,
		Agent:         raw.Agent,
		Model:         raw.Model,
		Date:          raw.Date,
		Overall:       math.Round(overall*10) / 10,
		Breakdown:     breakdown,
		TokensUsed:    raw.TotalTokens,
		TurnCount:     raw.TurnCount,
		DurationMs:    raw.DurationMs,
		FilesCount:    raw.FilesCount,
		FrictionCount: raw.FrictionCount,
	}
}

// scoreTokenEfficiency: fewer tokens per file = better.
// Benchmark: ~2000 tokens/file is good, ~10000+ is poor.
func scoreTokenEfficiency(raw RawSessionData) float64 {
	if raw.FilesCount == 0 || raw.TotalTokens == 0 {
		return 50 // neutral when no data
	}
	tokensPerFile := float64(raw.TotalTokens) / float64(raw.FilesCount)
	// Sigmoid-like mapping: 2000 tok/file → ~90, 5000 → ~65, 10000 → ~35
	score := 100 * math.Exp(-tokensPerFile/8000)
	return clampScore(score)
}

// scoreFirstPass: did the outcome match the intent?
// Without a summary, default to neutral (50).
func scoreFirstPass(raw RawSessionData) float64 {
	if !raw.HasSummary {
		return 50
	}
	// Base score starts at 80 (assumes sessions generally succeed)
	score := 80.0
	// Deduct for friction (each friction point = -10)
	score -= float64(raw.FrictionCount) * 10
	// Deduct for high turn count (>5 turns suggests iteration)
	if raw.TurnCount > 5 {
		score -= float64(raw.TurnCount-5) * 3
	}
	// Deduct for open items (unfinished work)
	score -= float64(len(raw.OpenItems)) * 5
	return clampScore(score)
}

// scoreFriction: fewer friction points = better.
func scoreFriction(raw RawSessionData) float64 {
	if raw.FrictionCount == 0 {
		return 100
	}
	// Each friction point costs ~20 points
	score := 100 - float64(raw.FrictionCount)*20
	return clampScore(score)
}

// scoreFocus: reasonable file count relative to turn count.
// Touching many files in few turns = focused. Many turns for few files = unfocused.
func scoreFocus(raw RawSessionData) float64 {
	if raw.TurnCount == 0 || raw.FilesCount == 0 {
		return 50
	}
	ratio := float64(raw.FilesCount) / float64(raw.TurnCount)
	// Ideal: ~1-2 files per turn. Low ratio = lots of churn on few files.
	if ratio >= 0.5 && ratio <= 3.0 {
		return 90
	}
	if ratio < 0.5 {
		return 50 + ratio*80 // Below 0.5 scales down
	}
	// ratio > 3.0: too scattered
	return clampScore(90 - (ratio-3)*10)
}

func clampScore(s float64) float64 {
	if s < 0 {
		return 0
	}
	if s > 100 {
		return 100
	}
	return math.Round(s*10) / 10
}
