	Path     string          `json:"path"`
	Exists   bool            `json:"exists"`
	Content  string          `json:"content,omitempty"`
	SizeBytes int            `json:"size_bytes"`
}

// Suggestion represents a proposed change to a context file.
type Suggestion struct {
	ID          string          `json:"id"`
	FileType    ContextFileType `json:"file_type"`
	FilePath    string          `json:"file_path"`
	Category    string          `json:"category"`    // "add_rule", "fix_friction", "optimize_tokens", "add_pattern"
	Title       string          `json:"title"`
	Description string          `json:"description"`
	Evidence    []string        `json:"evidence"`    // Session IDs or friction quotes that support this
	Priority    string          `json:"priority"`    // "high", "medium", "low"
	Diff        string          `json:"diff"`        // Unified diff of proposed change
	CreatedAt   time.Time       `json:"created_at"`
}

// ImprovementReport is the output of `entire improve`.
type ImprovementReport struct {
	ContextFiles  []ContextFile  `json:"context_files"`
	Suggestions   []Suggestion   `json:"suggestions"`
	SessionsUsed  int            `json:"sessions_used"`
	FrictionTotal int            `json:"friction_total"`
	PatternsFound int            `json:"patterns_found"`
}
