  1→package cli
  2→
  3→import (
  4→	"fmt"
  5→	"io"
  6→	"os"
  7→	"strconv"
  8→	"strings"
  9→	"time"
 10→
 11→	"github.com/charmbracelet/lipgloss"
 12→	"github.com/entireio/cli/cmd/entire/cli/agent"
 13→
 14→	"golang.org/x/term"
 15→)
 16→
 17→// statusStyles holds pre-built lipgloss styles and terminal metadata.
 18→type statusStyles struct {
 19→	colorEnabled bool
 20→	width        int
 21→
 22→	// Styles
 23→	green lipgloss.Style
 24→	red   lipgloss.Style
 25→	gray  lipgloss.Style
 26→	bold  lipgloss.Style
 27→	dim   lipgloss.Style
 28→	agent lipgloss.Style // amber/orange for agent names
 29→	cyan  lipgloss.Style
 30→}
 31→
 32→// newStatusStyles creates styles appropriate for the output writer.
 33→func newStatusStyles(w io.Writer) statusStyles {
 34→	useColor := shouldUseColor(w)
 35→	width := getTerminalWidth(w)
 36→
 37→	s := statusStyles{
 38→		colorEnabled: useColor,
 39→		width:        width,
 40→	}
 41→
 42→	if useColor {
 43→		s.green = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
 44→		s.red = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
 45→		s.gray = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
 46→		s.bold = lipgloss.NewStyle().Bold(true)
 47→		s.dim = lipgloss.NewStyle().Faint(true)
 48→		s.agent = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("214"))
 49→		s.cyan = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
 50→	}
 51→
 52→	return s
 53→}
 54→
 55→// render applies a style to text only when color is enabled.
 56→func (s statusStyles) render(style lipgloss.Style, text string) string {
 57→	if !s.colorEnabled {
 58→		return text
 59→	}
 60→	return style.Render(text)
 61→}
 62→
 63→// shouldUseColor returns true if the writer supports color output.
 64→func shouldUseColor(w io.Writer) bool {
 65→	if os.Getenv("NO_COLOR") != "" {
 66→		return false
 67→	}
 68→	if f, ok := w.(*os.File); ok {
 69→		return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
 70→	}
 71→	return false
 72→}
 73→
 74→// getTerminalWidth returns the terminal width, capped at 80 with a fallback of 60.
 75→// It first checks the writer itself, then falls back to Stdout/Stderr.
 76→func getTerminalWidth(w io.Writer) int {
 77→	// Try the output writer first
 78→	if f, ok := w.(*os.File); ok {
 79→		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
 80→			return min(width, 80)
 81→		}
 82→	}
 83→
 84→	// Fall back to Stdout, then Stderr
 85→	for _, f := range []*os.File{os.Stdout, os.Stderr} {
 86→		if f == nil {
 87→			continue
 88→		}
 89→		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
 90→			return min(width, 80)
 91→		}
 92→	}
 93→
 94→	return 60
 95→}
 96→
 97→// formatTokenCount formats a token count for display.
 98→// 0 → "0", 500 → "500", 1200 → "1.2k", 14300 → "14.3k"
 99→func formatTokenCount(n int) string {
100→	if n < 1000 {
101→		return strconv.Itoa(n)
102→	}
103→	f := float64(n) / 1000.0
104→	s := fmt.Sprintf("%.1f", f)
105→	// Remove trailing ".0" for clean display (e.g., 1000 → "1k" not "1.0k")
106→	s = strings.TrimSuffix(s, ".0")
107→	return s + "k"
108→}
109→
110→// totalTokens recursively sums all token fields including subagent tokens.
111→func totalTokens(tu *agent.TokenUsage) int {
112→	if tu == nil {
113→		return 0
114→	}
115→	total := tu.InputTokens + tu.CacheCreationTokens + tu.CacheReadTokens + tu.OutputTokens
116→	total += totalTokens(tu.SubagentTokens)
117→	return total
118→}
119→
120→// horizontalRule renders a dimmed horizontal rule of the given width.
121→func (s statusStyles) horizontalRule(width int) string {
122→	rule := strings.Repeat("─", width)
123→	return s.render(s.dim, rule)
124→}
125→
126→// sectionRule renders a section header like: ── Active Sessions ────────────
127→func (s statusStyles) sectionRule(label string, width int) string {
128→	prefix := "── "
129→	content := label + " "
130→	usedWidth := len([]rune(prefix)) + len([]rune(content))
131→	trailing := width - usedWidth
132→	if trailing < 1 {
133→		trailing = 1
134→	}
135→
136→	var b strings.Builder
137→	b.WriteString(s.render(s.dim, "── "))
138→	b.WriteString(s.render(s.dim, label))
139→	b.WriteString(" ")
140→	b.WriteString(s.render(s.dim, strings.Repeat("─", trailing)))
141→	return b.String()
142→}
143→
144→// activeTimeDisplay formats a last interaction time for display.
145→// Returns "active now" for recent activity (<1min), otherwise "active Xm ago".
146→func activeTimeDisplay(lastInteraction *time.Time) string {
147→	if lastInteraction == nil {
148→		return ""
149→	}
150→	d := time.Since(*lastInteraction)
151→	if d < time.Minute {
152→		return "active now"
153→	}
154→	return "active " + timeAgo(*lastInteraction)
155→}
