  1→// Package summarize provides AI-powered summarization of development sessions.
  2→package summarize
  3→
  4→import (
  5→	"context"
  6→	"encoding/json"
  7→	"errors"
  8→	"fmt"
  9→	"strings"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/agent"
 12→	"github.com/entireio/cli/cmd/entire/cli/agent/factoryaidroid"
 13→	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
 14→	"github.com/entireio/cli/cmd/entire/cli/agent/opencode"
 15→	"github.com/entireio/cli/cmd/entire/cli/agent/types"
 16→	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
 17→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 18→)
 19→
 20→// GenerateFromTranscript generates a summary from raw transcript bytes.
 21→// This is the shared implementation used by both explain --generate and auto-summarize.
 22→//
 23→// Parameters:
 24→//   - ctx: context for cancellation
 25→//   - transcriptBytes: raw transcript bytes (JSONL or JSON format depending on agent)
 26→//   - filesTouched: list of files modified during the session
 27→//   - agentType: the agent type to determine transcript format
 28→//   - generator: summary generator to use (if nil, uses default ClaudeGenerator)
 29→//
 30→// Returns nil, error if transcript is empty or cannot be parsed.
 31→func GenerateFromTranscript(ctx context.Context, transcriptBytes []byte, filesTouched []string, agentType types.AgentType, generator Generator) (*checkpoint.Summary, error) {
 32→	if len(transcriptBytes) == 0 {
 33→		return nil, errors.New("empty transcript")
 34→	}
 35→
 36→	// Build condensed transcript for summarization
 37→	condensed, err := BuildCondensedTranscriptFromBytes(transcriptBytes, agentType)
 38→	if err != nil {
 39→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
 40→	}
 41→	if len(condensed) == 0 {
 42→		return nil, errors.New("transcript has no content to summarize")
 43→	}
 44→
 45→	input := Input{
 46→		Transcript:   condensed,
 47→		FilesTouched: filesTouched,
 48→	}
 49→
 50→	// Use default generator if none provided
 51→	if generator == nil {
 52→		generator = &ClaudeGenerator{}
 53→	}
 54→
 55→	summary, err := generator.Generate(ctx, input)
 56→	if err != nil {
 57→		return nil, fmt.Errorf("failed to generate summary: %w", err)
 58→	}
 59→
 60→	return summary, nil
 61→}
 62→
 63→// Generator generates checkpoint summaries using an LLM.
 64→type Generator interface {
 65→	// Generate creates a summary from checkpoint data.
 66→	// Returns the generated summary or an error if generation fails.
 67→	Generate(ctx context.Context, input Input) (*checkpoint.Summary, error)
 68→}
 69→
 70→// Input contains condensed checkpoint data for summarization.
 71→type Input struct {
 72→	// Transcript is the condensed transcript entries
 73→	Transcript []Entry
 74→
 75→	// FilesTouched are the files modified during the session
 76→	FilesTouched []string
 77→}
 78→
 79→// EntryType represents the type of a transcript entry.
 80→type EntryType string
 81→
 82→const (
 83→	// EntryTypeUser indicates a user prompt entry.
 84→	EntryTypeUser EntryType = "user"
 85→	// EntryTypeAssistant indicates an assistant response entry.
 86→	EntryTypeAssistant EntryType = "assistant"
 87→	// EntryTypeTool indicates a tool call entry.
 88→	EntryTypeTool EntryType = "tool"
 89→)
 90→
 91→// Entry represents one item in the condensed transcript.
 92→type Entry struct {
 93→	// Type is the entry type (user, assistant, tool)
 94→	Type EntryType
 95→
 96→	// Content is the text content for user/assistant entries
 97→	Content string
 98→
 99→	// ToolName is the name of the tool (for tool entries)
100→	ToolName string
101→
102→	// ToolDetail is a description or file path (for tool entries)
103→	ToolDetail string
104→}
105→
106→// minimalDetailTools lists tools that should show only essential details in summaries.
107→// These tools often have verbose outputs that don't add value to summarization.
108→// The detail shown is typically just a path, URL, or identifier rather than full content.
109→var minimalDetailTools = map[string]bool{
110→	"Skill":    true, // Show skill name only, not loaded content
111→	"Read":     true, // Show file path only, not file contents
112→	"WebFetch": true, // Show URL only, not fetched content
113→}
114→
115→// BuildCondensedTranscriptFromBytes parses transcript bytes and extracts a condensed view.
116→// This is a convenience function that combines parsing and condensing.
117→// The agentType parameter determines which parser to use (Claude/OpenCode JSONL vs Gemini JSON).
118→func BuildCondensedTranscriptFromBytes(content []byte, agentType types.AgentType) ([]Entry, error) {
119→	switch agentType {
120→	case agent.AgentTypeGemini:
121→		return buildCondensedTranscriptFromGemini(content)
122→	case agent.AgentTypeFactoryAIDroid:
123→		return buildCondensedTranscriptFromDroid(content)
124→	case agent.AgentTypeOpenCode:
125→		return buildCondensedTranscriptFromOpenCode(content)
126→	case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeUnknown:
127→		// Claude/cursor format - fall through to shared logic below
128→	}
129→	// Claude format (JSONL) - handles Claude Code, Unknown, and any future agent types
130→	lines, err := transcript.ParseFromBytes(content)
131→	if err != nil {
132→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
133→	}
134→	return BuildCondensedTranscript(lines), nil
135→}
136→
137→// buildCondensedTranscriptFromGemini parses Gemini JSON transcript and extracts a condensed view.
138→func buildCondensedTranscriptFromGemini(content []byte) ([]Entry, error) {
139→	geminiTranscript, err := geminicli.ParseTranscript(content)
140→	if err != nil {
141→		return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
142→	}
143→
144→	var entries []Entry
145→	for _, msg := range geminiTranscript.Messages {
146→		switch msg.Type {
147→		case geminicli.MessageTypeUser:
148→			if msg.Content != "" {
149→				entries = append(entries, Entry{
150→					Type:    EntryTypeUser,
151→					Content: msg.Content,
152→				})
153→			}
154→		case geminicli.MessageTypeGemini:
155→			// Add assistant content
156→			if msg.Content != "" {
157→				entries = append(entries, Entry{
158→					Type:    EntryTypeAssistant,
159→					Content: msg.Content,
160→				})
161→			}
162→			// Add tool calls
163→			for _, tc := range msg.ToolCalls {
164→				entries = append(entries, Entry{
165→					Type:       EntryTypeTool,
166→					ToolName:   tc.Name,
167→					ToolDetail: extractGenericToolDetail(tc.Args),
168→				})
169→			}
170→		}
171→	}
172→
173→	return entries, nil
174→}
175→
176→// buildCondensedTranscriptFromOpenCode parses OpenCode export JSON transcript and extracts a condensed view.
177→func buildCondensedTranscriptFromOpenCode(content []byte) ([]Entry, error) {
178→	session, err := opencode.ParseExportSession(content)
179→	if err != nil {
180→		return nil, fmt.Errorf("failed to parse OpenCode transcript: %w", err)
181→	}
182→	if session == nil {
183→		return nil, nil
184→	}
185→
186→	var entries []Entry
187→	for _, msg := range session.Messages {
188→		switch msg.Info.Role {
189→		case "user":
190→			text := opencode.ExtractTextFromParts(msg.Parts)
191→			if text != "" {
192→				entries = append(entries, Entry{
193→					Type:    EntryTypeUser,
194→					Content: text,
195→				})
196→			}
197→		case "assistant":
198→			text := opencode.ExtractTextFromParts(msg.Parts)
199→			if text != "" {
200→				entries = append(entries, Entry{
201→					Type:    EntryTypeAssistant,
202→					Content: text,
203→				})
204→			}
205→			for _, part := range msg.Parts {
206→				if part.Type == "tool" && part.State != nil {
207→					entries = append(entries, Entry{
208→						Type:       EntryTypeTool,
209→						ToolName:   part.Tool,
210→						ToolDetail: extractOpenCodeToolDetail(part.State.Input),
211→					})
212→				}
213→			}
214→		}
215→	}
216→
217→	return entries, nil
218→}
219→
220→// buildCondensedTranscriptFromDroid parses Droid transcript and extracts a condensed view.
221→func buildCondensedTranscriptFromDroid(content []byte) ([]Entry, error) {
222→	droidLines, _, err := factoryaidroid.ParseDroidTranscriptFromBytes(content, 0)
223→	if err != nil {
224→		return nil, fmt.Errorf("failed to parse Droid transcript: %w", err)
225→	}
226→	return BuildCondensedTranscript(droidLines), nil
227→}
228→
229→// extractOpenCodeToolDetail extracts a detail string from an OpenCode tool's input map.
230→// OpenCode uses camelCase keys (e.g., "filePath" instead of "file_path").
231→func extractOpenCodeToolDetail(input map[string]interface{}) string {
232→	for _, key := range []string{"description", "command", "filePath", "path", "pattern"} {
233→		if v, ok := input[key].(string); ok && v != "" {
234→			return v
235→		}
236→	}
237→	return ""
238→}
239→
240→// extractGenericToolDetail extracts an appropriate detail string from a tool's input/args map.
241→// Checks common fields in order of preference. Used by Gemini condensation.
242→func extractGenericToolDetail(input map[string]interface{}) string {
243→	for _, key := range []string{"description", "command", "file_path", "path", "pattern"} {
244→		if v, ok := input[key].(string); ok && v != "" {
245→			return v
246→		}
247→	}
248→	return ""
249→}
250→
251→// BuildCondensedTranscript extracts a condensed view of the transcript.
252→// It processes user prompts, assistant responses, and tool calls into
253→// a simplified format suitable for LLM summarization.
254→func BuildCondensedTranscript(lines []transcript.Line) []Entry {
255→	var entries []Entry
256→
257→	for _, line := range lines {
258→		switch line.Type {
259→		case transcript.TypeUser:
260→			if entry := extractUserEntry(line); entry != nil {
261→				entries = append(entries, *entry)
262→			}
263→		case transcript.TypeAssistant:
264→			assistantEntries := extractAssistantEntries(line)
265→			entries = append(entries, assistantEntries...)
266→		}
267→	}
268→
269→	return entries
270→}
271→
272→// skillContentPrefix identifies user messages that are skill content injections.
273→// These are injected after a Skill tool call and contain the full skill instructions.
274→const skillContentPrefix = "Base directory for this skill:"
275→
276→// extractUserEntry extracts a user entry from a transcript line.
277→// Returns nil if the line doesn't contain a valid user prompt or is skill content.
278→func extractUserEntry(line transcript.Line) *Entry {
279→	content := transcript.ExtractUserContent(line.Message)
280→	if content == "" {
281→		return nil
282→	}
283→
284→	// Skip skill content injections - these are verbose skill instructions
285→	// injected as user messages after Skill tool invocations in Claude Code.
286→	// The prefix "Base directory for this skill:" is added by the superpowers
287→	// plugin when loading skill content. This filtering reduces transcript noise
288→	// since skill content is documentation, not user intent.
289→	if strings.HasPrefix(content, skillContentPrefix) {
290→		return nil
291→	}
292→
293→	return &Entry{
294→		Type:    EntryTypeUser,
295→		Content: content,
296→	}
297→}
