299→// extractAssistantEntries extracts assistant and tool entries from a transcript line.
300→func extractAssistantEntries(line transcript.Line) []Entry {
301→	var msg transcript.AssistantMessage
302→	if err := json.Unmarshal(line.Message, &msg); err != nil {
303→		return nil
304→	}
305→
306→	var entries []Entry
307→
308→	for _, block := range msg.Content {
309→		switch block.Type {
310→		case transcript.ContentTypeText:
311→			if block.Text != "" {
312→				entries = append(entries, Entry{
313→					Type:    EntryTypeAssistant,
314→					Content: block.Text,
315→				})
316→			}
317→		case transcript.ContentTypeToolUse:
318→			var input transcript.ToolInput
319→			_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
320→
321→			detail := extractToolDetail(block.Name, input)
322→
323→			entries = append(entries, Entry{
324→				Type:       EntryTypeTool,
325→				ToolName:   block.Name,
326→				ToolDetail: detail,
327→			})
328→		}
329→	}
330→
331→	return entries
332→}
