334→// extractToolDetail extracts an appropriate detail string for a tool call.
335→// For tools in minimalDetailTools, only essential identifiers are shown.
336→// For other tools, the full detail chain is used.
337→func extractToolDetail(toolName string, input transcript.ToolInput) string {
338→	// For minimal detail tools, extract only the essential identifier
339→	if minimalDetailTools[toolName] {
340→		switch toolName {
341→		case "Skill":
342→			return input.Skill
343→		case "Read":
344→			if input.FilePath != "" {
345→				return input.FilePath
346→			}
347→			return input.NotebookPath
348→		case "WebFetch":
349→			return input.URL
350→		}
351→	}
352→
353→	// For other tools, use the full detail chain
354→	if input.Description != "" {
355→		return input.Description
356→	}
357→	if input.Command != "" {
358→		return input.Command
359→	}
360→	if input.FilePath != "" {
361→		return input.FilePath
362→	}
363→	if input.NotebookPath != "" {
364→		return input.NotebookPath
365→	}
366→	return input.Pattern
367→}
