369→// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
370→// The format is:
371→//
372→//	[User] user prompt here
373→//
374→//	[Assistant] assistant response here
375→//
376→//	[Tool] ToolName: description or file path
377→func FormatCondensedTranscript(input Input) string {
378→	var sb strings.Builder
379→
380→	for i, entry := range input.Transcript {
381→		if i > 0 {
382→			sb.WriteString("\n")
383→		}
384→
385→		switch entry.Type {
386→		case EntryTypeUser:
387→			sb.WriteString("[User] ")
388→			sb.WriteString(entry.Content)
389→			sb.WriteString("\n")
390→		case EntryTypeAssistant:
391→			sb.WriteString("[Assistant] ")
392→			sb.WriteString(entry.Content)
393→			sb.WriteString("\n")
394→		case EntryTypeTool:
395→			sb.WriteString("[Tool] ")
396→			sb.WriteString(entry.ToolName)
397→			if entry.ToolDetail != "" {
398→				sb.WriteString(": ")
399→				sb.WriteString(entry.ToolDetail)
400→			}
401→			sb.WriteString("\n")
402→		}
403→	}
404→
405→	if len(input.FilesTouched) > 0 {
406→		sb.WriteString("\n[Files Modified]\n")
407→		for _, file := range input.FilesTouched {
408→			fmt.Fprintf(&sb, "- %s\n", file)
409→		}
410→	}
411→
412→	return sb.String()
413→}
