687→// ComputeTrends analyzes score history to detect improvement/decline patterns.
688→func ComputeTrends(scores []SessionScore) []Trend {
689→	if len(scores) == 0 {
690→		return nil
691→	}
692→
693→	// Sort by date ascending
694→	sorted := make([]SessionScore, len(scores))
695→	copy(sorted, scores)
696→	sort.Slice(sorted, func(i, j int) bool {
697→		return sorted[i].Date.Before(sorted[j].Date)
698→	})
699→
700→	return []Trend{
701→		computeTrend("overall_score", sorted, func(s SessionScore) float64 { return s.Overall }),
702→		computeTrend("token_usage", sorted, func(s SessionScore) float64 { return float64(s.TokensUsed) }),
703→		computeTrend("friction", sorted, func(s SessionScore) float64 { return float64(s.FrictionCount) }),
704→		computeTrend("turns_per_session", sorted, func(s SessionScore) float64 { return float64(s.TurnCount) }),
705→	}
706→}
707→
708→func computeTrend(metric string, scores []SessionScore, extract func(SessionScore) float64) Trend {
709→	points := make([]DataPoint, len(scores))
710→	for i, s := range scores {
711→		points[i] = DataPoint{
712→			Date:  s.Date,
713→			Value: extract(s),
714→			Label: s.SessionID,
715→		}
716→	}
717→
718→	trend := Trend{
719→		Metric:     metric,
720→		DataPoints: points,
721→	}
722→
723→	if len(scores) < 2 {
724→		trend.Direction = "stable"
725→		return trend
726→	}
727→
728→	// Compare first half average to second half average
729→	mid := len(points) / 2
730→	firstHalf := avgValues(points[:mid])
731→	secondHalf := avgValues(points[mid:])
732→
733→	if firstHalf == 0 {
734→		trend.Direction = "stable"
735→		return trend
736→	}
737→
738→	change := (secondHalf - firstHalf) / math.Abs(firstHalf) * 100
739→	trend.ChangePercent = math.Round(change*10) / 10
740→
741→	// For metrics where lower is better (tokens, friction, turns), invert the direction
742→	inverted := metric == "token_usage" || metric == "friction" || metric == "turns_per_session"
743→
744→	switch {
745→	case math.Abs(change) < 5:
746→		trend.Direction = "stable"
747→	case (change > 0 && !inverted) || (change < 0 && inverted):
748→		trend.Direction = "improving"
749→	default:
750→		trend.Direction = "declining"
751→	}
752→
753→	return trend
754→}
755→
756→func avgValues(points []DataPoint) float64 {
757→	if len(points) == 0 {
758→		return 0
759→	}
760→	var sum float64
761→	for _, p := range points {
762→		sum += p.Value
763→	}
764→	return sum / float64(len(points))
765→}
