1603→// FrictionPattern represents a recurring friction theme.
1604→type FrictionPattern struct {
1605→	Theme    string   // Normalized theme description
1606→	Count    int      // Number of sessions with this friction
1607→	Examples []string // Raw friction strings from sessions
