1611→// AnalyzePatterns extracts recurring patterns from session summaries.
1612→func AnalyzePatterns(summaries []SessionSummaryData) PatternAnalysis {
1613→	analysis := PatternAnalysis{
1614→		SessionCount: len(summaries),
1615→	}
1616→
1617→	// Collect all friction points with deduplication by theme
1618→	frictionIndex := make(map[string]*FrictionPattern)
1619→	repoLearningsSet := make(map[string]bool)
1620→	workflowSet := make(map[string]bool)
1621→
1622→	for _, sd := range summaries {
1623→		if sd.Summary == nil {
1624→			continue
1625→		}
1626→
1627→		// Analyze friction
1628→		for _, f := range sd.Summary.Friction {
1629→			theme := normalizeFriction(f)
1630→			if existing, ok := frictionIndex[theme]; ok {
1631→				existing.Count++
1632→				existing.Examples = append(existing.Examples, f)
1633→				existing.Sessions = append(existing.Sessions, sd.SessionID)
1634→			} else {
1635→				frictionIndex[theme] = &FrictionPattern{
1636→					Theme:    theme,
1637→					Count:    1,
1638→					Examples: []string{f},
1639→					Sessions: []string{sd.SessionID},
1640→				}
1641→			}
1642→		}
1643→
1644→		// Collect learnings
1645→		for _, l := range sd.Summary.Learnings.Repo {
1646→			if !repoLearningsSet[l] {
1647→				repoLearningsSet[l] = true
1648→				analysis.RepoLearnings = append(analysis.RepoLearnings, l)
1649→			}
1650→		}
1651→		for _, l := range sd.Summary.Learnings.Workflow {
1652→			if !workflowSet[l] {
1653→				workflowSet[l] = true
1654→				analysis.WorkflowLearnings = append(analysis.WorkflowLearnings, l)
1655→			}
1656→		}
1657→		analysis.CodeLearnings = append(analysis.CodeLearnings, sd.Summary.Learnings.Code...)
1658→		analysis.OpenItems = append(analysis.OpenItems, sd.Summary.OpenItems...)
1659→	}
1660→
1661→	// Only include friction that appears 2+ times as "repeated"
1662→	for _, fp := range frictionIndex {
1663→		if fp.Count >= 2 {
1664→			analysis.RepeatedFriction = append(analysis.RepeatedFriction, *fp)
1665→		}
1666→	}
1667→
1668→	return analysis
1669→}
1670→
1671→// normalizeFriction extracts a normalized theme from a friction description.
1672→// Groups similar friction like "lint error" and "linter failed" under the same theme.
1673→func normalizeFriction(friction string) string {
1674→	lower := strings.ToLower(friction)
1675→
1676→	// Common friction theme keywords
1677→	themes := []struct {
1678→		keywords []string
1679→		theme    string
1680→	}{
1681→		{[]string{"lint", "linter", "golangci"}, "linting issues"},
1682→		{[]string{"import", "missing import"}, "missing imports"},
1683→		{[]string{"test", "failing test", "test fail"}, "test failures"},
1684→		{[]string{"type", "type error", "type mismatch"}, "type errors"},
1685→		{[]string{"compile", "build", "syntax"}, "compilation errors"},
1686→		{[]string{"format", "gofmt", "formatting"}, "formatting issues"},
1687→		{[]string{"permission", "access", "auth"}, "permission issues"},
1688→		{[]string{"timeout", "slow", "hang"}, "performance issues"},
1689→		{[]string{"retry", "retried", "again"}, "required retries"},
1690→	}
1691→
1692→	for _, t := range themes {
1693→		for _, kw := range t.keywords {
1694→			if strings.Contains(lower, kw) {
1695→				return t.theme
1696→			}
1697→		}
1698→	}
1699→
1700→	// If no known theme, use the first 50 chars as a unique-ish key
1701→	if len(friction) > 50 {
1702→		return strings.ToLower(friction[:50])
1703→	}
1704→	return strings.ToLower(friction)
1705→}
