2655→package evolve
2656→
2657→import (
2658→	"fmt"
2659→	"time"
2660→)
2661→
2662→// Tracker manages the lifecycle of improvement suggestions.
2663→type Tracker struct {
2664→	Records map[string]*SuggestionRecord
2665→}
2666→
2667→// NewTracker creates a new suggestion tracker.
2668→func NewTracker() *Tracker {
2669→	return &Tracker{
2670→		Records: make(map[string]*SuggestionRecord),
2671→	}
2672→}
2673→
2674→// AddSuggestion registers a new suggestion.
2675→func (t *Tracker) AddSuggestion(rec SuggestionRecord) {
2676→	if rec.CreatedAt.IsZero() {
2677→		rec.CreatedAt = time.Now()
2678→	}
2679→	t.Records[rec.ID] = &rec
2680→}
2681→
2682→// Get returns a suggestion by ID, or nil if not found.
2683→func (t *Tracker) Get(id string) *SuggestionRecord {
2684→	return t.Records[id]
2685→}
2686→
2687→// Accept marks a suggestion as accepted.
2688→func (t *Tracker) Accept(id string) error {
2689→	rec, ok := t.Records[id]
2690→	if !ok {
2691→		return fmt.Errorf("suggestion %q not found", id)
2692→	}
2693→	rec.Status = "accepted"
2694→	now := time.Now()
2695→	rec.ResolvedAt = &now
2696→	return nil
2697→}
2698→
2699→// Reject marks a suggestion as rejected.
2700→func (t *Tracker) Reject(id string) error {
2701→	rec, ok := t.Records[id]
2702→	if !ok {
2703→		return fmt.Errorf("suggestion %q not found", id)
2704→	}
2705→	rec.Status = "rejected"
2706→	now := time.Now()
2707→	rec.ResolvedAt = &now
2708→	return nil
2709→}
2710→
2711→// MeasureImpact calculates the before/after score impact of a suggestion.
2712→func (t *Tracker) MeasureImpact(id string, scoresBefore, scoresAfter []float64) *SuggestionRecord {
2713→	rec, ok := t.Records[id]
2714→	if !ok {
2715→		return nil
2716→	}
2717→
2718→	if len(scoresBefore) > 0 {
2719→		avg := average(scoresBefore)
2720→		rec.ImpactBefore = &avg
2721→	}
2722→	if len(scoresAfter) > 0 {
2723→		avg := average(scoresAfter)
2724→		rec.ImpactAfter = &avg
2725→	}
2726→
2727→	return rec
2728→}
2729→
2730→// Pending returns all suggestions with "pending" status.
2731→func (t *Tracker) Pending() []SuggestionRecord {
2732→	var pending []SuggestionRecord
2733→	for _, rec := range t.Records {
2734→		if rec.Status == "pending" {
2735→			pending = append(pending, *rec)
2736→		}
2737→	}
2738→	return pending
2739→}
2740→
2741→func average(vals []float64) float64 {
2742→	if len(vals) == 0 {
2743→		return 0
2744→	}
2745→	var sum float64
2746→	for _, v := range vals {
2747→		sum += v
2748→	}
2749→	return sum / float64(len(vals))
2750→}
