package insights

import (
	"math"
	"sort"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// ComputeTrends analyzes score history to detect improvement/decline patterns.
func ComputeTrends(scores []SessionScore) []Trend {
	if len(scores) == 0 {
		return nil
	}

	// Sort by date ascending
	sorted := make([]SessionScore, len(scores))
	copy(sorted, scores)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].Date.Before(sorted[j].Date)
	})

	return []Trend{
		computeTrend("overall_score", sorted, func(s SessionScore) float64 { return s.Overall }),
		computeTrend("token_usage", sorted, func(s SessionScore) float64 { return float64(s.TokensUsed) }),
		computeTrend("friction", sorted, func(s SessionScore) float64 { return float64(s.FrictionCount) }),
		computeTrend("turns_per_session", sorted, func(s SessionScore) float64 { return float64(s.TurnCount) }),
	}
}

func computeTrend(metric string, scores []SessionScore, extract func(SessionScore) float64) Trend {
	points := make([]DataPoint, len(scores))
	for i, s := range scores {
		points[i] = DataPoint{
			Date:  s.Date,
			Value: extract(s),
			Label: s.SessionID,
		}
	}

	trend := Trend{
		Metric:     metric,
		DataPoints: points,
	}

	if len(scores) < 2 {
		trend.Direction = "stable"
		return trend
	}

	// Compare first half average to second half average
	mid := len(points) / 2
	firstHalf := avgValues(points[:mid])
	secondHalf := avgValues(points[mid:])

	if firstHalf == 0 {
		trend.Direction = "stable"
		return trend
	}

	change := (secondHalf - firstHalf) / math.Abs(firstHalf) * 100
	trend.ChangePercent = math.Round(change*10) / 10

	// For metrics where lower is better (tokens, friction, turns), invert the direction
	inverted := metric == "token_usage" || metric == "friction" || metric == "turns_per_session"

	switch {
	case math.Abs(change) < 5:
		trend.Direction = "stable"
	case (change > 0 && !inverted) || (change < 0 && inverted):
		trend.Direction = "improving"
	default:
		trend.Direction = "declining"
	}

	return trend
}

func avgValues(points []DataPoint) float64 {
	if len(points) == 0 {
		return 0
	}
	var sum float64
	for _, p := range points {
		sum += p.Value
	}
	return sum / float64(len(points))
}

// ComputeAgentComparisons groups scores by agent and computes averages.
func ComputeAgentComparisons(scores []SessionScore) []AgentComparison {
	byAgent := make(map[types.AgentType][]SessionScore)
	for _, s := range scores {
		byAgent[s.Agent] = append(byAgent[s.Agent], s)
	}

	var comparisons []AgentComparison
	for agentType, agentScores := range byAgent {
		comp := AgentComparison{
			Agent:        agentType,
			SessionCount: len(agentScores),
		}

		var totalScore float64
		var totalTokens, totalTurns, totalFriction int
		for _, s := range agentScores {
			totalScore += s.Overall
			totalTokens += s.TokensUsed
			totalTurns += s.TurnCount
			totalFriction += s.FrictionCount
		}

		n := float64(len(agentScores))
		comp.AvgScore = math.Round(totalScore/n*10) / 10
		comp.AvgTokens = int(math.Round(float64(totalTokens) / n))
		comp.AvgTurns = math.Round(float64(totalTurns)/n*10) / 10
		comp.AvgFriction = math.Round(float64(totalFriction)/n*10) / 10

		// Determine strengths/weaknesses from breakdown averages
		comp.TopStrength, comp.TopWeakness = identifyStrengthWeakness(agentScores)

		comparisons = append(comparisons, comp)
	}

	// Sort by average score descending
	sort.Slice(comparisons, func(i, j int) bool {
		return comparisons[i].AvgScore > comparisons[j].AvgScore
	})

	return comparisons
}

func identifyStrengthWeakness(scores []SessionScore) (strength, weakness string) {
	var te, fp, fr, fo float64
	for _, s := range scores {
		te += s.Breakdown.TokenEfficiency
		fp += s.Breakdown.FirstPassSuccess
		fr += s.Breakdown.FrictionScore
		fo += s.Breakdown.FocusScore
	}
	n := float64(len(scores))
	avgs := map[string]float64{
		"token efficiency": te / n,
		"first-pass success": fp / n,
		"low friction": fr / n,
		"focus": fo / n,
	}

	var maxK, minK string
	var maxV float64
	minV := 101.0
	for k, v := range avgs {
		if v > maxV {
			maxV = v
			maxK = k
		}
		if v < minV {
			minV = v
			minK = k
		}
	}
	return maxK, minK
}
