package cli

import (
	"context"
	"fmt"
	"io"

	cpkg "github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/improve"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/spf13/cobra"
)

func newImproveCmd() *cobra.Command {
	var (
		last    int
		dryRun  bool
	)

	cmd := &cobra.Command{
		Use:   "improve",
		Short: "Suggest improvements to project context files based on session patterns",
		Long: `Analyze friction patterns and learnings from recent sessions to generate
targeted improvements for CLAUDE.md, AGENTS.md, .cursorrules, and other context files.

Examples:
  entire improve              # Analyze last 10 sessions
  entire improve --last 30    # Analyze last 30 sessions
  entire improve --dry-run    # Show what would be analyzed without calling AI`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
				return nil
			}
			return runImprove(cmd.Context(), cmd.OutOrStdout(), last, dryRun)
		},
	}

	cmd.Flags().IntVar(&last, "last", 10, "Number of recent sessions to analyze")
	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "Show analysis without generating suggestions")

	return cmd
}

func runImprove(ctx context.Context, w io.Writer, last int, dryRun bool) error {
	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("failed to find repo root: %w", err)
	}

	store := cpkg.NewGitStore(repo)
	committed, err := store.ListCommitted(ctx)
	if err != nil {
		return fmt.Errorf("failed to list checkpoints: %w", err)
	}

	// Collect session summaries
	var summaries []improve.SessionSummaryData
	for _, cp := range committed {
		// Read full checkpoint summary to get session count
		summary, err := store.ReadCommitted(ctx, cp.CheckpointID)
		if err != nil || summary == nil {
			continue
		}

		for i := range summary.Sessions {
			content, err := store.ReadSessionContent(ctx, cp.CheckpointID, i)
			if err != nil {
				continue
			}
			if content.Metadata.Summary != nil {
				summaries = append(summaries, improve.SessionSummaryData{
					SessionID: content.Metadata.SessionID,
					Summary:   content.Metadata.Summary,
				})
			}
		}
	}

	// Limit to most recent N
	if len(summaries) > last {
		summaries = summaries[len(summaries)-last:]
	}

	if len(summaries) == 0 {
		fmt.Fprintln(w, "No sessions with summaries found. Enable summarization in .entire/settings.json:")
		fmt.Fprintln(w, `  { "strategy_options": { "summarize": { "enabled": true } } }`)
		return nil
	}

	// Analyze patterns
	analysis := improve.AnalyzePatterns(summaries)

	// Detect context files
	contextFiles := improve.DetectContextFiles(repoRoot)

	report := improve.ImprovementReport{
		ContextFiles:  contextFiles,
		SessionsUsed:  len(summaries),
		FrictionTotal: totalFriction(summaries),
		PatternsFound: len(analysis.RepeatedFriction),
	}

	if dryRun {
		fmt.Fprintf(w, "Dry run: analyzed %d sessions, found %d friction patterns\n",
			len(summaries), len(analysis.RepeatedFriction))
		for _, fp := range analysis.RepeatedFriction {
			fmt.Fprintf(w, "  [%dx] %s\n", fp.Count, fp.Theme)
		}
		return nil
	}

	// Generate suggestions via Claude
	fmt.Fprintln(w, "Analyzing patterns and generating suggestions...")
	gen := &improve.ClaudeGenerator{}
	suggestions, err := gen.Generate(ctx, analysis, contextFiles)
	if err != nil {
		return fmt.Errorf("failed to generate suggestions: %w", err)
	}

	report.Suggestions = suggestions
	improve.RenderImprovementReport(w, report)
	return nil
}

func totalFriction(summaries []improve.SessionSummaryData) int {
	var total int
	for _, s := range summaries {
		if s.Summary != nil {
			total += len(s.Summary.Friction)
		}
	}
	return total
}
