// Package evolve implements the automatic improvement loop that triggers
// context file improvement suggestions after configurable session thresholds.
package evolve

import "time"

// Config holds evolution loop settings.
type Config struct {
	Enabled            bool `json:"enabled"`
	SessionThreshold   int  `json:"session_threshold"`    // Sessions before auto-trigger (default 5)
	AutoApply          bool `json:"auto_apply"`           // Auto-apply low-risk suggestions
}

// DefaultConfig returns the default evolution configuration.
func DefaultConfig() Config {
	return Config{
		Enabled:          false, // Opt-in
		SessionThreshold: 5,
	}
}

// State tracks the evolution loop's progress.
type State struct {
	LastRunAt            time.Time `json:"last_run_at"`
	SessionsSinceLastRun int       `json:"sessions_since_last_run"`
	TotalRuns            int       `json:"total_runs"`
	SuggestionsGenerated int       `json:"suggestions_generated"`
	SuggestionsAccepted  int       `json:"suggestions_accepted"`
	SuggestionsRejected  int       `json:"suggestions_rejected"`
}

// SuggestionRecord tracks a suggestion through its lifecycle.
