// Styles holds pre-built lipgloss styles and terminal metadata.
type Styles struct {
	ColorEnabled bool
	Width        int

	Green  lipgloss.Style
	Red    lipgloss.Style
	Yellow lipgloss.Style
	Gray   lipgloss.Style
	Bold   lipgloss.Style
	Dim    lipgloss.Style
	Agent  lipgloss.Style
	Cyan   lipgloss.Style
