// SessionScore represents a quality assessment of a single session.
type SessionScore struct {
	SessionID   string         `json:"session_id"`
	Agent       types.AgentType `json:"agent"`
	Model       string         `json:"model"`
	Date        time.Time      `json:"date"`
	Overall     float64        `json:"overall"`     // 0-100 composite score
	Breakdown   ScoreBreakdown `json:"breakdown"`
	TokensUsed  int            `json:"tokens_used"`
	TurnCount   int            `json:"turn_count"`
	DurationMs  int64          `json:"duration_ms"`
	FilesCount  int            `json:"files_count"`
	FrictionCount int          `json:"friction_count"`
}

// ScoreBreakdown shows individual scoring dimensions.
type ScoreBreakdown struct {
	TokenEfficiency  float64 `json:"token_efficiency"`   // 0-100: tokens per file touched
	FirstPassSuccess float64 `json:"first_pass_success"` // 0-100: outcome vs intent alignment
	FrictionScore    float64 `json:"friction_score"`     // 0-100: inverse of friction count
	FocusScore       float64 `json:"focus_score"`        // 0-100: files touched vs intent scope
}

// Trend represents a metric tracked over time.
type Trend struct {
	Metric     string       `json:"metric"`
	Direction  string       `json:"direction"` // "improving", "declining", "stable"
	ChangePercent float64   `json:"change_percent"`
	DataPoints []DataPoint  `json:"data_points"`
}

// DataPoint is a single observation in a trend.
type DataPoint struct {
	Date  time.Time `json:"date"`
	Value float64   `json:"value"`
	Label string    `json:"label,omitempty"` // e.g., session ID
}

// AgentComparison summarizes performance differences between agents.
type AgentComparison struct {
	Agent          types.AgentType `json:"agent"`
	SessionCount   int             `json:"session_count"`
	AvgScore       float64         `json:"avg_score"`
	AvgTokens      int             `json:"avg_tokens"`
	AvgTurns       float64         `json:"avg_turns"`
	AvgFriction    float64         `json:"avg_friction"`
	TopStrength    string          `json:"top_strength"`    // e.g., "token efficiency"
	TopWeakness    string          `json:"top_weakness"`    // e.g., "friction rate"
}

// InsightsReport is the full output of `entire insights`.
type InsightsReport struct {
	Sessions    []SessionScore    `json:"sessions"`
	Trends      []Trend           `json:"trends"`
	Comparisons []AgentComparison `json:"comparisons"`
	Period      string            `json:"period"` // e.g., "last 30 days"
}
