	Evidence    []string        `json:"evidence"`    // Session IDs or friction quotes that support this
	Priority    string          `json:"priority"`    // "high", "medium", "low"
	Diff        string          `json:"diff"`        // Unified diff of proposed change
	CreatedAt   time.Time       `json:"created_at"`
}

// ImprovementReport is the output of `entire improve`.
