	if raw.TotalTokens != 1500 {
		t.Errorf("TotalTokens = %d, want %d", raw.TotalTokens, 1500)
	}
	if raw.FilesCount != 2 {
		t.Errorf("FilesCount = %d, want %d", raw.FilesCount, 2)
	}
	if raw.FrictionCount != 1 {
		t.Errorf("FrictionCount = %d, want %d", raw.FrictionCount, 1)
	}
	if raw.TurnCount != 3 {
		t.Errorf("TurnCount = %d, want %d", raw.TurnCount, 3)
	}
	if raw.HasSummary != true {
