package insights

import (
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"time"
)

// RawSessionData holds extracted metrics from a checkpoint for scoring.
type RawSessionData struct {
	SessionID     string
	Agent         types.AgentType
	Model         string
	Date          time.Time
	TotalTokens   int
	InputTokens   int
	OutputTokens  int
	CacheTokens   int
	FilesCount    int
	FilesTouched  []string
	FrictionCount int
	Friction      []string
	TurnCount     int
	DurationMs    int64
	HasSummary    bool
	Intent        string
	Outcome       string
	Learnings     *checkpoint.LearningsSummary
	OpenItems     []string
}

// AggregateSession extracts raw metrics from a CommittedMetadata for scoring.
func AggregateSession(meta *checkpoint.CommittedMetadata) RawSessionData {
	raw := RawSessionData{
		SessionID:    meta.SessionID,
		Agent:        meta.Agent,
		Model:        meta.Model,
		Date:         meta.CreatedAt,
		FilesCount:   len(meta.FilesTouched),
		FilesTouched: meta.FilesTouched,
	}

	if meta.TokenUsage != nil {
		raw.InputTokens = meta.TokenUsage.InputTokens + meta.TokenUsage.CacheCreationTokens + meta.TokenUsage.CacheReadTokens
		raw.OutputTokens = meta.TokenUsage.OutputTokens
		raw.CacheTokens = meta.TokenUsage.CacheReadTokens
		raw.TotalTokens = raw.InputTokens + raw.OutputTokens
		// Include subagent tokens
		if meta.TokenUsage.SubagentTokens != nil {
			sub := meta.TokenUsage.SubagentTokens
			raw.TotalTokens += sub.InputTokens + sub.CacheCreationTokens +
				sub.CacheReadTokens + sub.OutputTokens
		}
	}

	if meta.SessionMetrics != nil {
		raw.TurnCount = meta.SessionMetrics.TurnCount
		raw.DurationMs = meta.SessionMetrics.DurationMs
	}

	if meta.Summary != nil {
		raw.HasSummary = true
		raw.Intent = meta.Summary.Intent
		raw.Outcome = meta.Summary.Outcome
		raw.FrictionCount = len(meta.Summary.Friction)
		raw.Friction = meta.Summary.Friction
		raw.Learnings = &meta.Summary.Learnings
		raw.OpenItems = meta.Summary.OpenItems
	}

	return raw
}
```

