package improve

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

// Generator generates improvement suggestions using an LLM.
type Generator interface {
	Generate(ctx context.Context, analysis PatternAnalysis, contextFiles []ContextFile) ([]Suggestion, error)
}

// ClaudeGenerator uses the Claude CLI to generate improvement suggestions.
type ClaudeGenerator struct {
	ClaudePath    string
	Model         string
	CommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd // for testing
}

const defaultModel = "sonnet"

// Generate calls Claude to produce context file improvement suggestions.
func (g *ClaudeGenerator) Generate(ctx context.Context, analysis PatternAnalysis, contextFiles []ContextFile) ([]Suggestion, error) {
	prompt := buildImprovementPrompt(analysis, contextFiles)

	claudePath := g.ClaudePath
	if claudePath == "" {
		claudePath = "claude"
	}
	model := g.Model
	if model == "" {
		model = defaultModel
	}

	runner := g.CommandRunner
	if runner == nil {
		runner = exec.CommandContext
	}

	cmd := runner(ctx, claudePath, "--print", "--output-format", "json", "--model", model, "--max-turns", "1", "--setting-sources", "")
	cmd.Stdin = strings.NewReader(prompt)
	cmd.Dir = os.TempDir()
	cmd.Env = stripGitEnv(os.Environ())

	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("claude CLI failed: %w", err)
	}

	// Parse Claude CLI JSON response — format is {"result": "string"}
	var resp struct {
		Result string `json:"result"`
	}
	if err := json.Unmarshal(out, &resp); err != nil {
		return nil, fmt.Errorf("failed to parse claude response: %w", err)
	}

	// Extract JSON from markdown code blocks if present
	text := extractJSON(resp.Result)

	return parseImprovementResponse([]byte(text))
}

func buildImprovementPrompt(analysis PatternAnalysis, contextFiles []ContextFile) string {
	var b strings.Builder

	b.WriteString("Analyze these patterns from recent AI coding sessions and suggest improvements to the project's context files.\n\n")

	// Friction patterns
	if len(analysis.RepeatedFriction) > 0 {
		b.WriteString("<repeated_friction>\n")
		for _, fp := range analysis.RepeatedFriction {
			fmt.Fprintf(&b, "Theme: %s (occurred %d times)\n", fp.Theme, fp.Count)
			for _, ex := range fp.Examples {
				fmt.Fprintf(&b, "  - %s\n", ex)
			}
		}
		b.WriteString("</repeated_friction>\n\n")
	}

	// Learnings
	if len(analysis.RepoLearnings) > 0 || len(analysis.WorkflowLearnings) > 0 {
		b.WriteString("<learnings>\n")
		for _, l := range analysis.RepoLearnings {
			fmt.Fprintf(&b, "Repo: %s\n", l)
		}
		for _, l := range analysis.WorkflowLearnings {
			fmt.Fprintf(&b, "Workflow: %s\n", l)
		}
		b.WriteString("</learnings>\n\n")
	}

	// Current context files
	b.WriteString("<current_context_files>\n")
	for _, cf := range contextFiles {
		if cf.Exists {
			fmt.Fprintf(&b, "--- %s (%d bytes) ---\n%s\n--- end ---\n\n", cf.Path, cf.SizeBytes, cf.Content)
		} else {
			fmt.Fprintf(&b, "--- %s (does not exist) ---\n\n", string(cf.Type))
		}
	}
	b.WriteString("</current_context_files>\n\n")

	b.WriteString(`Return a JSON object with this exact structure:
{
  "suggestions": [
    {
      "file_type": "CLAUDE.md",
      "category": "fix_friction|add_rule|optimize_tokens|add_pattern",
      "title": "Short title for the suggestion",
      "description": "Why this change helps and what evidence supports it",
      "evidence": ["session-id-1", "friction quote 1"],
      "priority": "high|medium|low",
      "diff": "Unified diff showing the proposed change"
    }
  ]
}

Guidelines:
- Focus on changes that address REPEATED friction (problems occurring 2+ times)
- Incorporate discovered learnings that are NOT already in the context files
- Each suggestion should have a clear unified diff showing exactly what to add/change
- Prioritize "high" for friction occurring 3+ times, "medium" for 2 times, "low" for learnings
- Do NOT suggest removing existing content unless it contradicts discovered patterns
- Keep suggestions concise and actionable`)

	return b.String()
}

func parseImprovementResponse(data []byte) ([]Suggestion, error) {
	var resp struct {
		Suggestions []struct {
			FileType    string   `json:"file_type"`
			Category    string   `json:"category"`
			Title       string   `json:"title"`
			Description string   `json:"description"`
			Evidence    []string `json:"evidence"`
			Priority    string   `json:"priority"`
			Diff        string   `json:"diff"`
		} `json:"suggestions"`
	}

	if err := json.Unmarshal(data, &resp); err != nil {
		return nil, fmt.Errorf("failed to parse suggestions JSON: %w", err)
	}

	suggestions := make([]Suggestion, len(resp.Suggestions))
	for i, s := range resp.Suggestions {
		suggestions[i] = Suggestion{
			ID:          fmt.Sprintf("sug-%d-%d", time.Now().Unix(), i),
			FileType:    ContextFileType(s.FileType),
			Category:    s.Category,
			Title:       s.Title,
			Description: s.Description,
			Evidence:    s.Evidence,
			Priority:    s.Priority,
			Diff:        s.Diff,
			CreatedAt:   time.Now(),
		}
	}

	return suggestions, nil
}

func extractJSON(text string) string {
	// Try to find JSON in markdown code blocks
	if idx := strings.Index(text, "```json"); idx >= 0 {
		start := idx + len("```json")
		if end := strings.Index(text[start:], "```"); end >= 0 {
			return strings.TrimSpace(text[start : start+end])
		}
	}
	if idx := strings.Index(text, "```"); idx >= 0 {
		start := idx + len("```")
		if end := strings.Index(text[start:], "```"); end >= 0 {
			return strings.TrimSpace(text[start : start+end])
		}
	}
	return text
}

func stripGitEnv(env []string) []string {
	var filtered []string
	for _, e := range env {
		if !strings.HasPrefix(e, "GIT_") {
			filtered = append(filtered, e)
		}
	}
	return filtered
}
