```go
// Package termstyle provides shared terminal styling utilities for the CLI.
package termstyle

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"github.com/charmbracelet/lipgloss"
	"github.com/entireio/cli/cmd/entire/cli/agent"
	"golang.org/x/term"
)

// Styles holds pre-built lipgloss styles and terminal metadata.
type Styles struct {
	ColorEnabled bool
	Width        int

	Green  lipgloss.Style
	Red    lipgloss.Style
	Yellow lipgloss.Style
	Gray   lipgloss.Style
	Bold   lipgloss.Style
	Dim    lipgloss.Style
	Agent  lipgloss.Style
	Cyan   lipgloss.Style
}

// New creates styles appropriate for the output writer.
func New(w io.Writer) Styles {
	useColor := ShouldUseColor(w)
	width := GetTerminalWidth(w)

	s := Styles{ColorEnabled: useColor, Width: width}
	if useColor {
		s.Green = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
		s.Red = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
		s.Yellow = lipgloss.NewStyle().Foreground(lipgloss.Color("3"))
		s.Gray = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
		s.Bold = lipgloss.NewStyle().Bold(true)
		s.Dim = lipgloss.NewStyle().Faint(true)
		s.Agent = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("214"))
		s.Cyan = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
	}
	return s
}

// Render applies a style to text only when color is enabled.
func (s Styles) Render(style lipgloss.Style, text string) string {
	if !s.ColorEnabled {
		return text
	}
	return style.Render(text)
}

// ShouldUseColor returns true if the writer supports color output.
func ShouldUseColor(w io.Writer) bool {
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	if f, ok := w.(*os.File); ok {
		return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115
	}
	return false
}

// GetTerminalWidth returns terminal width capped at 80, fallback 60.
func GetTerminalWidth(w io.Writer) int {
	if f, ok := w.(*os.File); ok {
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115
			return min(width, 80)
		}
	}
	for _, f := range []*os.File{os.Stdout, os.Stderr} {
		if f == nil {
			continue
		}
		if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115
			return min(width, 80)
		}
	}
	return 60
}

// FormatTokenCount formats a token count: 0→"0", 500→"500", 1200→"1.2k".
func FormatTokenCount(n int) string {
	if n < 1000 {
		return strconv.Itoa(n)
	}
	f := float64(n) / 1000.0
	s := fmt.Sprintf("%.1f", f)
	s = strings.TrimSuffix(s, ".0")
	return s + "k"
}

// TotalTokens recursively sums all token fields including subagent tokens.
func TotalTokens(tu *agent.TokenUsage) int {
	if tu == nil {
		return 0
	}
	total := tu.InputTokens + tu.CacheCreationTokens + tu.CacheReadTokens + tu.OutputTokens
	total += TotalTokens(tu.SubagentTokens)
	return total
}

// SectionRule renders "── Label ────────────".
func (s Styles) SectionRule(label string) string {
	prefix := "── "
	content := label + " "
	usedWidth := len([]rune(prefix)) + len([]rune(content))
	trailing := s.Width - usedWidth
	if trailing < 1 {
		trailing = 1
	}
	var b strings.Builder
	b.WriteString(s.Render(s.Dim, "── "))
	b.WriteString(s.Render(s.Dim, label))
	b.WriteString(" ")
	b.WriteString(s.Render(s.Dim, strings.Repeat("─", trailing)))
	return b.String()
}

// HorizontalRule renders a dimmed horizontal rule.
func (s Styles) HorizontalRule() string {
	return s.Render(s.Dim, strings.Repeat("─", s.Width))
}
