295→// addTaskMetadataToTree adds task checkpoint metadata to a git tree.
296→// When IsIncremental is true, only adds the incremental checkpoint file.
297→//
298→// Uses ApplyTreeChanges (tree surgery) instead of FlattenTree+BuildTreeFromEntries,
299→// so only affected subtrees are read/rebuilt.
300→func (s *GitStore) addTaskMetadataToTree(ctx context.Context, baseTreeHash plumbing.Hash, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
301→	// Compute metadata paths
302→	sessionMetadataDir := paths.EntireMetadataDir + "/" + opts.SessionID
303→	taskMetadataDir := sessionMetadataDir + "/tasks/" + opts.ToolUseID
304→
305→	var changes []TreeChange
306→
307→	if opts.IsIncremental {
308→		// Incremental checkpoint: only add the checkpoint file
309→		var incData []byte
310→		var err error
311→		if opts.IncrementalData != nil {
312→			incData, err = redact.JSONLBytes(opts.IncrementalData)
313→			if err != nil {
314→				return plumbing.ZeroHash, fmt.Errorf("failed to redact incremental checkpoint: %w", err)
315→			}
316→		}
317→		incrementalCheckpoint := struct {
318→			Type      string          `json:"type"`
319→			ToolUseID string          `json:"tool_use_id"`
320→			Timestamp time.Time       `json:"timestamp"`
321→			Data      json.RawMessage `json:"data"`
322→		}{
323→			Type:      opts.IncrementalType,
324→			ToolUseID: opts.ToolUseID,
325→			Timestamp: time.Now().UTC(),
326→			Data:      incData,
327→		}
328→		cpData, err := jsonutil.MarshalIndentWithNewline(incrementalCheckpoint, "", "  ")
329→		if err != nil {
330→			return plumbing.ZeroHash, fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
331→		}
332→
333→		cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
334→		if err != nil {
335→			return plumbing.ZeroHash, fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
336→		}
337→		cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
338→		cpPath := taskMetadataDir + "/checkpoints/" + cpFilename
339→		changes = append(changes, TreeChange{
340→			Path:  cpPath,
341→			Entry: &object.TreeEntry{Mode: filemode.Regular, Hash: cpBlobHash},
342→		})
343→	} else {
344→		// Final checkpoint: add transcripts and checkpoint.json
345→
346→		// Add session transcript (with chunking support for large transcripts)
347→		if opts.TranscriptPath != "" {
348→			if transcriptContent, readErr := os.ReadFile(opts.TranscriptPath); readErr == nil {
349→				agentType := agent.DetectAgentTypeFromContent(transcriptContent)
350→
351→				// Chunk if necessary
352→				chunks, chunkErr := agent.ChunkTranscript(ctx, transcriptContent, agentType)
353→				if chunkErr != nil {
354→					logging.Warn(ctx, "failed to chunk transcript, checkpoint will be saved without transcript",
355→						slog.String("error", chunkErr.Error()),
356→						slog.String("session_id", opts.SessionID),
357→					)
358→				} else {
359→					for i, chunk := range chunks {
360→						chunkPath := sessionMetadataDir + "/" + agent.ChunkFileName(paths.TranscriptFileName, i)
361→						blobHash, blobErr := CreateBlobFromContent(s.repo, chunk)
362→						if blobErr != nil {
363→							logging.Warn(ctx, "failed to create blob for transcript chunk",
364→								slog.String("error", blobErr.Error()),
365→								slog.String("session_id", opts.SessionID),
366→								slog.Int("chunk_index", i),
367→							)
368→							continue
369→						}
370→						changes = append(changes, TreeChange{
371→							Path:  chunkPath,
372→							Entry: &object.TreeEntry{Mode: filemode.Regular, Hash: blobHash},
373→						})
374→					}
375→				}
376→			}
377→		}
378→
379→		// Add subagent transcript if available
380→		if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
381→			if agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath); readErr == nil {
382→				redacted, jsonlErr := redact.JSONLBytes(agentContent)
383→				if jsonlErr != nil {
384→					logging.Warn(ctx, "subagent transcript is not valid JSONL, falling back to plain redaction",
385→						slog.String("path", opts.SubagentTranscriptPath),
386→						slog.String("error", jsonlErr.Error()),
387→					)
388→					redacted = redact.Bytes(agentContent)
389→				}
390→				agentContent = redacted
391→				if blobHash, blobErr := CreateBlobFromContent(s.repo, agentContent); blobErr == nil {
392→					agentPath := taskMetadataDir + "/agent-" + opts.AgentID + ".jsonl"
393→					changes = append(changes, TreeChange{
394→						Path:  agentPath,
395→						Entry: &object.TreeEntry{Mode: filemode.Regular, Hash: blobHash},
396→					})
397→				}
398→			}
399→		}

200→		headCommitHash:        o.headCommitHash,
201→	})
202→
203→	// Get current branch name
204→	branchName := GetCurrentBranchName(repo)
205→
206→	// Generate summary if enabled
207→	var summary *cpkg.Summary
208→	if settings.IsSummarizeEnabled(ctx) && len(sessionData.Transcript) > 0 {
209→		summarizeCtx := logging.WithComponent(ctx, "summarize")
210→
211→		var scopedTranscript []byte
212→		switch state.AgentType {
213→		case agent.AgentTypeGemini:
214→			scoped, sliceErr := geminicli.SliceFromMessage(sessionData.Transcript, state.CheckpointTranscriptStart)
215→			if sliceErr != nil {
216→				logging.Warn(summarizeCtx, "failed to scope Gemini transcript for summary",
217→					slog.String("session_id", state.SessionID),
218→					slog.String("error", sliceErr.Error()))
219→			}
220→			scopedTranscript = scoped
221→		case agent.AgentTypeOpenCode:
222→			scoped, sliceErr := opencode.SliceFromMessage(sessionData.Transcript, state.CheckpointTranscriptStart)
223→			if sliceErr != nil {
224→				logging.Warn(summarizeCtx, "failed to scope OpenCode transcript for summary",
225→					slog.String("session_id", state.SessionID),
226→					slog.String("error", sliceErr.Error()))
227→			}
228→			scopedTranscript = scoped
229→		case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeFactoryAIDroid, agent.AgentTypeUnknown:
230→			scopedTranscript = transcript.SliceFromLine(sessionData.Transcript, state.CheckpointTranscriptStart)
231→		}
232→		if len(scopedTranscript) > 0 {
233→			var err error
234→			summary, err = summarize.GenerateFromTranscript(summarizeCtx, scopedTranscript, sessionData.FilesTouched, state.AgentType, nil)
235→			if err != nil {
236→				logging.Warn(summarizeCtx, "summary generation failed",
237→					slog.String("session_id", state.SessionID),
238→					slog.String("error", err.Error()))
239→			} else {
240→				logging.Info(summarizeCtx, "summary generated",
241→					slog.String("session_id", state.SessionID))
242→			}
243→		}
244→	}
245→
246→	// Write checkpoint metadata using the checkpoint store
247→	if err := store.WriteCommitted(ctx, cpkg.WriteCommittedOptions{
248→		CheckpointID:                checkpointID,
249→		SessionID:                   state.SessionID,
250→		Strategy:                    StrategyNameManualCommit,
251→		Branch:                      branchName,
252→		Transcript:                  sessionData.Transcript,
253→		Prompts:                     sessionData.Prompts,
254→		FilesTouched:                sessionData.FilesTouched,
255→		CheckpointsCount:            state.StepCount,
256→		EphemeralBranch:             shadowBranchName,
257→		AuthorName:                  authorName,
258→		AuthorEmail:                 authorEmail,
259→		Agent:                       state.AgentType,
260→		Model:                       state.ModelName,
261→		TurnID:                      state.TurnID,
262→		TranscriptIdentifierAtStart: state.TranscriptIdentifierAtStart,
263→		CheckpointTranscriptStart:   state.CheckpointTranscriptStart,
264→		TokenUsage:                  sessionData.TokenUsage,
265→		SessionMetrics:              buildSessionMetrics(state),
266→		InitialAttribution:          attribution,
267→		Summary:                     summary,
268→	}); err != nil {
269→		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
270→	}
271→
272→	return &CondenseResult{
273→		CheckpointID:         checkpointID,
274→		SessionID:            state.SessionID,
275→		CheckpointsCount:     state.StepCount,
276→		FilesTouched:         sessionData.FilesTouched,
277→		Prompts:              sessionData.Prompts,
278→		TotalTranscriptLines: sessionData.FullTranscriptLines,
279→		Transcript:           sessionData.Transcript,
280→	}, nil
281→}
