120→// ListCheckpoints returns all checkpoints from the entire/checkpoints/v1 branch.
121→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
122→func ListCheckpoints(ctx context.Context) ([]CheckpointInfo, error) {
123→	repo, err := OpenRepository(ctx)
124→	if err != nil {
125→		return nil, fmt.Errorf("failed to open git repository: %w", err)
126→	}
127→
128→	// Warn (once per process) if metadata branches are disconnected
129→	WarnIfMetadataDisconnected()
130→
131→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
132→	ref, err := repo.Reference(refName, true)
133→	if err != nil {
134→		//nolint:nilerr // No sessions branch yet is expected, return empty list
135→		return []CheckpointInfo{}, nil
136→	}
137→
138→	commit, err := repo.CommitObject(ref.Hash())
139→	if err != nil {
140→		return nil, fmt.Errorf("failed to get commit object: %w", err)
141→	}
142→
143→	tree, err := commit.Tree()
144→	if err != nil {
145→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
146→	}
147→
148→	var checkpoints []CheckpointInfo
149→
150→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
151→	// The tree has 2-character directories (hex buckets)
152→	for _, bucketEntry := range tree.Entries {
153→		if bucketEntry.Mode != filemode.Dir {
154→			continue
155→		}
156→		// Bucket should be 2 hex chars
157→		if len(bucketEntry.Name) != 2 {
158→			continue
159→		}
160→
161→		bucketTree, treeErr := repo.TreeObject(bucketEntry.Hash)
162→		if treeErr != nil {
163→			continue
164→		}
165→
166→		// Each entry in the bucket is the remaining part of the checkpoint ID
167→		for _, checkpointEntry := range bucketTree.Entries {
168→			if checkpointEntry.Mode != filemode.Dir {
169→				continue
170→			}
171→
172→			checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
173→			if cpTreeErr != nil {
174→				continue
175→			}
176→
177→			// Reconstruct checkpoint ID: <bucket><remaining>
178→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
179→			checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
180→			if cpErr != nil {
181→				// Skip invalid checkpoint IDs
182→				continue
183→			}
184→
185→			info := CheckpointInfo{
186→				CheckpointID: checkpointID,
187→			}
188→
189→			// Get details from metadata file (CheckpointSummary format)
190→			if summary, ok := decodeSummaryLiteFromTree(checkpointTree); ok {
191→				info.CheckpointsCount = summary.CheckpointsCount
192→				info.FilesTouched = summary.FilesTouched
193→				info.SessionCount = len(summary.Sessions)
194→
195→				// Read session-level metadata for Agent, SessionID, CreatedAt, SessionIDs
196→				for i, sessionPaths := range summary.Sessions {
197→					if sessionPaths.Metadata == "" {
198→						continue
199→					}
200→					// SessionFilePaths contains absolute paths with leading "/"
201→					// Strip the leading "/" for tree.File() which expects paths without leading slash
202→					sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
203→					sessionMeta, sErr := decodeSessionMetadataLite(tree, sessionMetadataPath)
204→					if sErr != nil {
205→						continue
206→					}
207→					info.SessionIDs = append(info.SessionIDs, sessionMeta.SessionID)
208→					// Use first session's metadata for Agent, SessionID, CreatedAt
209→					if i == 0 {
210→						info.Agent = sessionMeta.Agent
211→						info.SessionID = sessionMeta.SessionID
212→						info.CreatedAt = sessionMeta.CreatedAt
213→						info.IsTask = sessionMeta.IsTask
214→						info.ToolUseID = sessionMeta.ToolUseID
215→					}
216→				}
217→			}
218→
219→			checkpoints = append(checkpoints, info)
220→		}
221→	}
222→
223→	// Sort by time (most recent first)
224→	sort.Slice(checkpoints, func(i, j int) bool {
225→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
226→	})
227→
228→	return checkpoints, nil
229→}
