238→// isProtectedPath returns true if relPath is inside a directory that should
239→// never be modified or deleted during rewind or other destructive operations.
240→// Protected directories include git internals, entire metadata, and all
241→// registered agent config directories.
242→func isProtectedPath(relPath string) bool {
243→	for _, dir := range protectedDirs() {
