275→// EnsureRedactionConfigured loads PII redaction settings and configures the
276→// redact package. No-op if PII is not enabled in settings.
277→// Must be called at each process entry point before checkpoint writes
278→// (e.g., hook PersistentPreRunE, doctor PreRun).
279→func EnsureRedactionConfigured() {
280→	initRedactionOnce.Do(func() {
281→		ctx := context.Background()
282→		s, err := settings.Load(ctx)
283→		if err != nil {
284→			logCtx := logging.WithComponent(ctx, "redaction")
285→			logging.Warn(logCtx, "failed to load settings for PII redaction", slog.String("error", err.Error()))
286→			return
287→		}
288→		if s.Redaction == nil || s.Redaction.PII == nil || !s.Redaction.PII.Enabled {
289→			return
290→		}
291→		pii := s.Redaction.PII
292→		cfg := redact.PIIConfig{
293→			Enabled:        true,
294→			Categories:     make(map[redact.PIICategory]bool),
295→			CustomPatterns: pii.CustomPatterns,
296→		}
297→		// Email and phone default to true when PII is enabled; address defaults to false.
298→		cfg.Categories[redact.PIIEmail] = pii.Email == nil || *pii.Email
299→		cfg.Categories[redact.PIIPhone] = pii.Phone == nil || *pii.Phone
300→		cfg.Categories[redact.PIIAddress] = pii.Address != nil && *pii.Address
301→		redact.ConfigurePII(cfg)
302→	})
303→}
