 18→// tree hashes to the old FlattenTree+BuildTreeFromEntries approach.
 19→func TestBuildTreeWithChanges_EquivalenceWithFlattenRebuild(t *testing.T) { //nolint:paralleltest // t.Chdir requires non-parallel
 20→	repo, dir := setupTestRepo(t)
