 36→	deletedFiles := []string{"file3.txt"}
 37→
 38→	// Write modified files to disk
 39→	for _, f := range modifiedFiles {
 40→		path := filepath.Join(dir, f)
 41→		if err := os.WriteFile(path, []byte("modified content for "+f), 0o600); err != nil {
 42→			t.Fatalf("write %s: %v", f, err)
 43→		}
 44→	}
