229→// flattenRebuildTree is the old FlattenTree+BuildTreeFromEntries approach
230→// for comparison in equivalence tests.
231→func flattenRebuildTree(
232→	t *testing.T, repo *gogit.Repository,
233→	baseTreeHash plumbing.Hash,
234→	modifiedFiles, deletedFiles []string,
235→	metadataDir, metadataDirAbs, repoRoot string,
236→) plumbing.Hash {
237→	t.Helper()
238→
239→	baseTree, err := repo.TreeObject(baseTreeHash)
240→	if err != nil {
241→		t.Fatalf("tree: %v", err)
242→	}
243→	entries := make(map[string]object.TreeEntry)
244→	if err := FlattenTree(repo, baseTree, "", entries); err != nil {
245→		t.Fatalf("flatten: %v", err)
246→	}
247→
248→	for _, file := range deletedFiles {
249→		delete(entries, file)
250→	}
251→
252→	for _, file := range modifiedFiles {
253→		absPath := filepath.Join(repoRoot, file)
254→		if !fileExists(absPath) {
255→			delete(entries, file)
256→			continue
257→		}
258→		blobHash, mode, blobErr := createBlobFromFile(repo, absPath)
259→		if blobErr != nil {
260→			continue
261→		}
262→		entries[file] = object.TreeEntry{
263→			Name: file,
264→			Mode: mode,
265→			Hash: blobHash,
266→		}
267→	}
268→
269→	if metadataDir != "" && metadataDirAbs != "" {
270→		if err := addDirectoryToEntriesWithAbsPath(repo, metadataDirAbs, metadataDir, entries); err != nil {
271→			t.Fatalf("add metadata: %v", err)
272→		}
273→	}
274→
275→	hash, err := BuildTreeFromEntries(repo, entries)
276→	if err != nil {
277→		t.Fatalf("build tree: %v", err)
278→	}
279→	return hash
280→}
