194→// runExplainCheckpoint explains a specific checkpoint.
195→// Supports both committed checkpoints (by checkpoint ID) and temporary checkpoints (by git SHA).
196→// First tries to match committed checkpoints, then falls back to temporary checkpoints.
197→// When generate is true, generates an AI summary for the checkpoint.
198→// When force is true, regenerates even if a summary already exists.
199→// When rawTranscript is true, outputs only the raw transcript file (JSONL format).
200→// When searchAll is true, searches all commits without branch/depth limits (used for finding associated commits).
201→func runExplainCheckpoint(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool) error {
202→	repo, err := openRepository(ctx)
203→	if err != nil {
204→		return fmt.Errorf("not a git repository: %w", err)
205→	}
206→
207→	store := checkpoint.NewGitStore(repo)
208→
209→	// First, try to find in committed checkpoints by checkpoint ID prefix
210→	committed, err := store.ListCommitted(ctx)
211→	if err != nil {
212→		return fmt.Errorf("failed to list checkpoints: %w", err)
213→	}
214→
215→	// Collect all matching checkpoint IDs to detect ambiguity
216→	var matches []id.CheckpointID
217→	for _, info := range committed {
218→		if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
219→			matches = append(matches, info.CheckpointID)
220→		}
221→	}
222→
223→	var fullCheckpointID id.CheckpointID
224→	switch len(matches) {
225→	case 0:
226→		// Not found in committed, try temporary checkpoints by git SHA
227→		if generate {
228→			return fmt.Errorf("cannot generate summary for temporary checkpoint %s (only committed checkpoints supported)", checkpointIDPrefix)
229→		}
230→		output, found := explainTemporaryCheckpoint(ctx, w, repo, store, checkpointIDPrefix, verbose, full, rawTranscript)
231→		if found {
232→			outputExplainContent(w, output, noPager)
233→			return nil
234→		}
235→		// If output is non-empty, it contains an error message (e.g., ambiguous prefix)
236→		if output != "" {
237→			return errors.New(output)
238→		}
239→		return fmt.Errorf("checkpoint not found: %s", checkpointIDPrefix)
240→	case 1:
241→		fullCheckpointID = matches[0]
242→	default:
243→		// Ambiguous prefix - show up to 5 examples
244→		examples := make([]string, 0, 5)
245→		for i := 0; i < len(matches) && i < 5; i++ {
246→			examples = append(examples, matches[i].String())
247→		}
248→		return fmt.Errorf("ambiguous checkpoint prefix %q matches %d checkpoints: %s", checkpointIDPrefix, len(matches), strings.Join(examples, ", "))
249→	}
250→
251→	// Load checkpoint summary
252→	summary, err := store.ReadCommitted(ctx, fullCheckpointID)
253→	if err != nil {
254→		return fmt.Errorf("failed to read checkpoint: %w", err)
255→	}
256→	if summary == nil {
257→		return fmt.Errorf("checkpoint not found: %s", fullCheckpointID)
258→	}
259→
260→	// Load latest session content (needed for transcript and metadata)
261→	content, err := store.ReadLatestSessionContent(ctx, fullCheckpointID)
262→	if err != nil {
263→		return fmt.Errorf("failed to read checkpoint content: %w", err)
264→	}
265→
266→	// Handle summary generation
267→	if generate {
268→		if err := generateCheckpointSummary(ctx, w, errW, store, fullCheckpointID, summary, content, force); err != nil {
269→			return err
270→		}
271→		// Reload the content to get the updated summary
272→		content, err = store.ReadLatestSessionContent(ctx, fullCheckpointID)
273→		if err != nil {
274→			return fmt.Errorf("failed to reload checkpoint: %w", err)
275→		}
276→	}
277→
278→	// Handle raw transcript output
279→	if rawTranscript {
280→		if len(content.Transcript) == 0 {
281→			return fmt.Errorf("checkpoint %s has no transcript", fullCheckpointID)
282→		}
283→		// Output raw transcript directly (no pager, no formatting)
284→		if _, err = w.Write(content.Transcript); err != nil {
285→			return fmt.Errorf("failed to write transcript: %w", err)
286→		}
287→		return nil
288→	}
