291→	associatedCommits, _ := getAssociatedCommits(ctx, repo, fullCheckpointID, searchAll) //nolint:errcheck // Best-effort
292→
293→	// Derive author from the first associated commit (the user who made the commit).
294→	// Fall back to GetCheckpointAuthor (walks entire/checkpoints/v1) for checkpoints
295→	// not reachable from the current branch.
296→	var author checkpoint.Author
297→	if len(associatedCommits) > 0 {
298→		author = checkpoint.Author{
299→			Name:  associatedCommits[0].Author,
300→			Email: associatedCommits[0].Email,
301→		}
302→	} else {
