432→// ListCheckpointsForBranch lists checkpoint commits for a shadow branch by name.
433→// Use this when you already have the full branch name (e.g., from ListTemporary).
434→// The sessionID filter, if provided, limits results to commits from that session.
435→func (s *GitStore) ListCheckpointsForBranch(ctx context.Context, branchName, sessionID string, limit int) ([]TemporaryCheckpointInfo, error) {
436→	return s.listCheckpointsForBranch(ctx, branchName, sessionID, limit)
