858→// addDirectoryToEntriesWithAbsPath recursively adds all files in a directory to the entries map.
859→func addDirectoryToEntriesWithAbsPath(repo *git.Repository, dirPathAbs, dirPathRel string, entries map[string]object.TreeEntry) error {
860→	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
861→		if err != nil {
862→			return err
863→		}
864→
865→		// Skip symlinks to prevent reading files outside the metadata directory.
866→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
867→		// then be captured in the checkpoint and stored in git history.
868→		// NOTE: filepath.Walk uses os.Stat (follows symlinks), so info.Mode() never
869→		// reports ModeSymlink. We use os.Lstat to check the entry itself.
870→		// This check MUST come before IsDir() because Walk follows symlinked
871→		// directories and would recurse into them otherwise.
872→		linfo, lstatErr := os.Lstat(path)
873→		if lstatErr != nil {
874→			return fmt.Errorf("failed to lstat %s: %w", path, lstatErr)
875→		}

875→		}
876→		if linfo.Mode()&os.ModeSymlink != 0 {
877→			if info.IsDir() {
878→				return filepath.SkipDir
879→			}
880→			return nil
881→		}
882→
883→		if info.IsDir() {
884→			return nil
885→		}
886→
887→		// Calculate relative path within the directory, then join with dirPathRel for tree entry
888→		relWithinDir, err := filepath.Rel(dirPathAbs, path)
889→		if err != nil {
890→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
891→		}
892→
893→		// Prevent path traversal via symlinks pointing outside the metadata dir
894→		if strings.HasPrefix(relWithinDir, "..") {
895→			return fmt.Errorf("path traversal detected: %s", relWithinDir)
896→		}
897→
898→		treePath := filepath.ToSlash(filepath.Join(dirPathRel, relWithinDir))
899→
900→		// Use redacted blob creation for metadata files (transcripts, prompts, etc.)
901→		// to ensure PII and secrets are redacted before writing to git.
902→		blobHash, mode, err := createRedactedBlobFromFile(repo, path, treePath)
903→		if err != nil {
904→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
905→		}
906→		entries[treePath] = object.TreeEntry{
907→			Name: treePath,
908→			Mode: mode,
909→			Hash: blobHash,
910→		}
911→		return nil
912→	})
913→	if err != nil {
914→		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
915→	}
916→	return nil
917→}
