930→	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
931→		if err != nil {
932→			return err
933→		}
934→
935→		// Skip symlinks (same security rationale as addDirectoryToEntriesWithAbsPath)
936→		linfo, lstatErr := os.Lstat(path)
937→		if lstatErr != nil {
