939→		}
940→		if linfo.Mode()&os.ModeSymlink != 0 {
941→			if info.IsDir() {
942→				return filepath.SkipDir
943→			}
944→			return nil
945→		}
946→
947→		if info.IsDir() {
948→			return nil
949→		}
950→
951→		relWithinDir, relErr := filepath.Rel(dirPathAbs, path)
952→		if relErr != nil {
953→			return fmt.Errorf("failed to get relative path for %s: %w", path, relErr)
954→		}
955→		if strings.HasPrefix(relWithinDir, "..") {
956→			return fmt.Errorf("path traversal detected: %s", relWithinDir)
957→		}
958→
959→		treePath := filepath.ToSlash(filepath.Join(dirPathRel, relWithinDir))
960→
961→		blobHash, mode, blobErr := createRedactedBlobFromFile(repo, path, treePath)
962→		if blobErr != nil {
963→			return fmt.Errorf("failed to create blob for %s: %w", path, blobErr)
