556→// extractToolUseIDFromPath extracts the ToolUseID from a task metadata directory path.
557→// Task metadata dirs have format: .entire/metadata/<session>/tasks/<toolUseID>
558→func extractToolUseIDFromPath(metadataDir string) string {
559→	parts := strings.Split(metadataDir, "/")
560→	if len(parts) >= 2 && parts[len(parts)-2] == "tasks" {
561→		return parts[len(parts)-1]
562→	}
563→	return ""
