569→// GetTranscriptFromCommit retrieves the transcript from a specific commit's tree.
570→// This is used for shadow branch checkpoints where the transcript is stored in the commit tree
571→// rather than on the entire/checkpoints/v1 branch.
572→// commitHash is the commit to read from, metadataDir is the path within the tree.
573→// agentType is used for reassembling chunked transcripts in the correct format.
574→// Handles both chunked and non-chunked transcripts.
575→func (s *GitStore) GetTranscriptFromCommit(ctx context.Context, commitHash plumbing.Hash, metadataDir string, agentType types.AgentType) ([]byte, error) {
576→	commit, err := s.repo.CommitObject(commitHash)
577→	if err != nil {
578→		return nil, fmt.Errorf("failed to get commit: %w", err)
579→	}
580→
581→	tree, err := commit.Tree()
582→	if err != nil {
583→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
584→	}
585→
586→	// Try to get the metadata subtree for chunk detection
587→	subTree, subTreeErr := tree.Tree(metadataDir)
588→	if subTreeErr == nil {
589→		// Use the helper function that handles chunking.
590→		// Wrap in FetchingTree with nil fetcher (temporary reads are always local).
591→		ft := &FetchingTree{inner: subTree}
592→		transcript, err := readTranscriptFromTree(ctx, ft, agentType)
593→		if err == nil && transcript != nil {
594→			return transcript, nil
595→		}
596→	}
597→
598→	// Fall back to direct file access (for backwards compatibility)
599→	transcriptPath := metadataDir + "/" + paths.TranscriptFileName
600→	if file, fileErr := tree.File(transcriptPath); fileErr == nil {
601→		content, contentErr := file.Contents()
602→		if contentErr == nil {
603→			return []byte(content), nil
604→		}
605→	}
606→
607→	transcriptPath = metadataDir + "/" + paths.TranscriptFileNameLegacy
608→	if file, fileErr := tree.File(transcriptPath); fileErr == nil {
609→		content, contentErr := file.Contents()
610→		if contentErr == nil {
611→			return []byte(content), nil
612→		}
613→	}
614→
615→	return nil, ErrNoTranscript
616→}
