627→// DeleteShadowBranch deletes the shadow branch for the given base commit and worktree.
628→// worktreeID should be empty for main worktree or the internal git worktree name for linked worktrees.
629→// Uses git CLI instead of go-git's RemoveReference because go-git v5 doesn't properly
630→// persist deletions with packed refs or worktrees.
631→func (s *GitStore) DeleteShadowBranch(ctx context.Context, baseCommit, worktreeID string) error {
632→	shadowBranchName := ShadowBranchNameForCommit(baseCommit, worktreeID)
633→	cmd := exec.CommandContext(ctx, "git", "branch", "-D", "--", shadowBranchName)
634→	if output, err := cmd.CombinedOutput(); err != nil {
635→		return fmt.Errorf("failed to delete shadow branch %s: %s: %w", shadowBranchName, strings.TrimSpace(string(output)), err)
636→	}
637→	return nil
638→}
