640→// ShadowBranchNameForCommit returns the shadow branch name for a base commit hash
641→// and worktree identifier. The worktree ID should be empty for the main worktree
642→// or the internal git worktree name for linked worktrees.
643→// Format: entire/<commit[:7]>-<hash(worktreeID)[:6]>
644→func ShadowBranchNameForCommit(baseCommit, worktreeID string) string {
645→	commitPart := baseCommit
646→	if len(baseCommit) >= ShadowBranchHashLength {
647→		commitPart = baseCommit[:ShadowBranchHashLength]
648→	}
649→	worktreeHash := HashWorktreeID(worktreeID)
650→	return ShadowBranchPrefix + commitPart + "-" + worktreeHash
651→}
652→
653→// ParseShadowBranchName extracts the commit prefix and worktree hash from a shadow branch name.
654→// Input format: "entire/<commit[:7]>-<worktreeHash[:6]>"
655→// Returns (commitPrefix, worktreeHash, ok). Returns ("", "", false) if not a valid shadow branch.
656→func ParseShadowBranchName(branchName string) (commitPrefix, worktreeHash string, ok bool) {
657→	if !strings.HasPrefix(branchName, ShadowBranchPrefix) {
658→		return "", "", false
659→	}
660→	suffix := strings.TrimPrefix(branchName, ShadowBranchPrefix)
661→
662→	// Find the last dash - everything before is commit prefix, after is worktree hash
663→	lastDash := strings.LastIndex(suffix, "-")
664→	if lastDash == -1 || lastDash == 0 || lastDash == len(suffix)-1 {
665→		// No dash, or dash at start/end - invalid format
666→		// Could be old format "entire/<commit[:7]>" without worktree hash
667→		return suffix, "", true // Return as commit prefix with empty worktree hash
668→	}
669→
670→	return suffix[:lastDash], suffix[lastDash+1:], true
671→}
