145→// getMetadataBranchCheckpoint returns the metadata branch tree and a checkpoint path
146→// (e.g., "ab/cdef123456") for benchmarking ReadCheckpointMetadata.
147→func getMetadataBranchCheckpoint(b *testing.B, repo *gogit.Repository) (*object.Tree, string) {
148→	b.Helper()
149→	tree := getMetadataBranchTree(b, repo)
150→
151→	// Find first valid checkpoint path: <2-char-bucket>/<remaining>
152→	for _, bucketEntry := range tree.Entries {
153→		if bucketEntry.Mode != filemode.Dir || len(bucketEntry.Name) != 2 {
154→			continue
155→		}
156→		bucketTree, err := repo.TreeObject(bucketEntry.Hash)
157→		if err != nil {
158→			continue
159→		}
160→		for _, cpEntry := range bucketTree.Entries {
161→			if cpEntry.Mode != filemode.Dir {
162→				continue
163→			}
164→			return tree, fmt.Sprintf("%s/%s", bucketEntry.Name, cpEntry.Name)
165→		}
166→	}
167→	b.Fatal("no checkpoint found on metadata branch")
168→	return nil, ""
169→}
