 19→
 20→const fallbackDeviceAuthPollInterval = time.Second
 21→const slowDownBackoff = 5 * time.Second
 22→const maxPollInterval = 30 * time.Second
 23→const maxExpiresIn = 15 * time.Minute
 24→const maxTransientErrors = 5
 25→
 26→// browserOpenFunc is the signature for opening a URL in the user's browser.
 27→type browserOpenFunc func(ctx context.Context, url string) error
 28→
 29→// deviceAuthClient abstracts the auth client so runLogin and waitForApproval can be unit-tested.
 30→type deviceAuthClient interface {
 31→	StartDeviceAuth(ctx context.Context) (*auth.DeviceAuthStart, error)
 32→	PollDeviceAuth(ctx context.Context, deviceCode string) (*auth.DeviceAuthPoll, error)
 33→	BaseURL() string
 34→}
 35→
 36→func newLoginCmd() *cobra.Command {
 37→	var insecureHTTPAuth bool
 38→
 39→	cmd := &cobra.Command{
 40→		Use:   "login",
 41→		Short: "Log in to Entire",
 42→		RunE: func(cmd *cobra.Command, _ []string) error {
 43→			client := auth.NewClient(nil)
 44→
 45→			if !insecureHTTPAuth {
 46→				if err := apiurl.RequireSecureURL(client.BaseURL()); err != nil {
 47→					return fmt.Errorf("base URL check: %w", err)
 48→				}
 49→			}
 50→
 51→			return runLogin(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), client, openBrowser)
 52→		},
 53→	}
 54→
 55→	cmd.Flags().BoolVar(&insecureHTTPAuth, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
 56→	if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
 57→		panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
 58→	}
 59→
 60→	return cmd
 61→}
 62→
 63→func runLogin(ctx context.Context, outW, errW io.Writer, client deviceAuthClient, openURL browserOpenFunc) error {
 64→	start, err := client.StartDeviceAuth(ctx)
 65→	if err != nil {
 66→		return fmt.Errorf("start login: %w", err)
 67→	}
 68→
 69→	fmt.Fprintf(outW, "Device code: %s\n", start.UserCode)
 70→	approvalURL := start.VerificationURI
 71→	if approvalURL == "" {
 72→		approvalURL = start.VerificationURIComplete
 73→	}
 74→
 75→	if canPromptInteractively() {
 76→		fmt.Fprintf(outW, "Press Enter to open %s in your browser...", approvalURL)
 77→
 78→		// Read from /dev/tty so we get a real keypress and don't consume piped stdin.
 79→		waitForEnter()
 80→
 81→		fmt.Fprintln(outW)
 82→
 83→		if err := openURL(ctx, approvalURL); err != nil {
 84→			fmt.Fprintf(errW, "Warning: failed to open browser: %v\n", err)
 85→			fmt.Fprintln(outW, "Open the approval URL in your browser to continue.")
 86→		}
 87→	} else {
 88→		fmt.Fprintf(outW, "Approval URL: %s\n", approvalURL)
 89→	}
 90→
 91→	fmt.Fprintln(outW, "Waiting for approval...")
 92→
 93→	token, err := waitForApproval(ctx, client, start.DeviceCode, start.ExpiresIn, start.Interval)
 94→	if err != nil {
 95→		return fmt.Errorf("complete login: %w", err)
 96→	}
 97→
 98→	store := auth.NewStore()
 99→
100→	if err := store.SaveToken(client.BaseURL(), token); err != nil {
101→		return fmt.Errorf("save auth token: %w", err)
102→	}
103→
104→	fmt.Fprintln(outW, "Login complete.")
105→	return nil
106→}
107→
108→func waitForApproval(ctx context.Context, poller deviceAuthClient, deviceCode string, expiresIn, interval int) (string, error) {
109→	expiry := time.Duration(expiresIn) * time.Second
110→	if expiry <= 0 || expiry > maxExpiresIn {
111→		expiry = maxExpiresIn
112→	}
113→	deadline := time.Now().Add(expiry)
114→	pollInterval := time.Duration(interval) * time.Second
115→	if pollInterval <= 0 {
116→		pollInterval = fallbackDeviceAuthPollInterval
117→	}
118→
119→	consecutiveErrors := 0
120→
121→	for {
122→		if time.Now().After(deadline) {
123→			return "", errors.New("device authorization expired")
124→		}
125→
126→		result, err := poller.PollDeviceAuth(ctx, deviceCode)
127→		if err != nil {
128→			consecutiveErrors++
129→			if consecutiveErrors >= maxTransientErrors {
130→				return "", fmt.Errorf("poll approval status (after %d consecutive failures): %w", consecutiveErrors, err)
131→			}
132→			// Transient error — wait and retry.
133→			select {
134→			case <-ctx.Done():
135→				return "", fmt.Errorf("wait for approval: %w", ctx.Err())
136→			case <-time.After(pollInterval):
137→			}
138→			continue
139→		}
140→		consecutiveErrors = 0
141→
142→		switch result.Error {
143→		case "":
144→			if result.AccessToken == "" {
145→				return "", errors.New("device authorization completed without a token")
146→			}
147→			return result.AccessToken, nil
148→		case "authorization_pending":
149→			// no-op, will sleep and retry below
150→		case "slow_down":
151→			pollInterval += slowDownBackoff
152→			if pollInterval > maxPollInterval {
153→				pollInterval = maxPollInterval
154→			}
155→		case "access_denied":
156→			return "", errors.New("device authorization denied")
157→		case "expired_token":
158→			return "", errors.New("device authorization expired")
159→		default:
160→			return "", fmt.Errorf("device authorization failed: %s", result.Error)
161→		}
162→
163→		select {
164→		case <-ctx.Done():
165→			return "", fmt.Errorf("wait for approval: %w", ctx.Err())
166→		case <-time.After(pollInterval):
167→		}
168→	}
169→}
170→
171→// waitForEnter reads a line from /dev/tty, blocking until the user presses Enter.
172→// If /dev/tty cannot be opened (e.g. on Windows), it returns immediately.
173→func waitForEnter() {
174→	tty, err := os.Open("/dev/tty")
175→	if err != nil {
176→		return
177→	}
178→	defer tty.Close()
179→
180→	reader := bufio.NewReader(tty)
181→	if _, err = reader.ReadString('\n'); err != nil {
182→		return
183→	}
184→}
185→
186→func openBrowser(ctx context.Context, browserURL string) error {
187→	u, err := url.Parse(browserURL)
188→	if err != nil || (u.Scheme != "https" && u.Scheme != "http") {
189→		return fmt.Errorf("refusing to open non-HTTP URL: %s", browserURL)
190→	}
191→
192→	var command string
193→	var args []string
194→
195→	switch runtime.GOOS {
196→	case "darwin":
197→		command = "open"
198→		args = []string{browserURL}
199→	case "linux":
200→		command = "xdg-open"
201→		args = []string{browserURL}
202→	case "windows":
203→		command = "cmd"
204→		args = []string{"/c", "start", "", browserURL}
205→	default:
206→		return fmt.Errorf("unsupported platform %s", runtime.GOOS)
207→	}
208→
209→	cmd := exec.CommandContext(ctx, command, args...)
210→	if err := cmd.Start(); err != nil {
211→		return fmt.Errorf("start browser command %q: %w", command, err)
212→	}
213→
214→	if err := cmd.Process.Release(); err != nil {
215→		return fmt.Errorf("release browser process: %w", err)
216→	}
217→
218→	return nil
219→}
