 41→// BuildEventPayload constructs the event payload for tracking.
 42→// Exported for testing. Returns nil if the payload cannot be built.
 43→func BuildEventPayload(cmd *cobra.Command, agent string, isEntireEnabled bool, version string) *EventPayload {
 44→	if cmd == nil {
 45→		return nil
 46→	}
 47→
 48→	// Get machine ID for distinct_id
 49→	machineID, err := machineid.ProtectedID("entire-cli")
 50→	if err != nil {
 51→		return nil
 52→	}
 53→
 54→	// Collect flag names (not values) for privacy
 55→	var flags []string
 56→	cmd.Flags().Visit(func(flag *pflag.Flag) {
 57→		flags = append(flags, flag.Name)
 58→	})
 59→
 60→	selectedAgent := agent
 61→	if selectedAgent == "" {
 62→		selectedAgent = "auto"
 63→	}
 64→
 65→	properties := map[string]any{
 66→		"command":         cmd.CommandPath(),
 67→		"agent":           selectedAgent,
 68→		"isEntireEnabled": isEntireEnabled,
 69→		"cli_version":     version,
 70→		"os":              runtime.GOOS,
 71→		"arch":            runtime.GOARCH,
 72→	}
 73→
 74→	if len(flags) > 0 {
 75→		properties["flags"] = strings.Join(flags, ",")
 76→	}
 77→
 78→	return &EventPayload{
 79→		Event:      "cli_command_executed",
 80→		DistinctID: machineID,
 81→		Properties: properties,
 82→		Timestamp:  time.Now(),
 83→	}
 84→}
 85→
 86→// TrackCommandDetached tracks a command execution by spawning a detached subprocess.
 87→// This returns immediately without blocking the CLI.
 88→func TrackCommandDetached(cmd *cobra.Command, agent string, isEntireEnabled bool, version string) {
 89→	// Check opt-out environment variables
 90→	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
 91→		return
 92→	}
 93→
 94→	if cmd == nil {
 95→		return
 96→	}
 97→
 98→	if cmd.Hidden {
 99→		return
100→	}
101→
102→	payload := BuildEventPayload(cmd, agent, isEntireEnabled, version)
103→	if payload == nil {
104→		return
105→	}
106→
107→	if payloadJSON, err := json.Marshal(payload); err == nil {
108→		spawnDetachedAnalytics(string(payloadJSON))
109→	}
110→}
111→
112→// SendEvent processes an event payload in the detached subprocess.
113→// This is called by the hidden __send_analytics command.
114→func SendEvent(payloadJSON string) {
115→	var payload EventPayload
116→	if err := json.Unmarshal([]byte(payloadJSON), &payload); err != nil {
117→		return
118→	}
119→
120→	// Create PostHog client - no need for fast timeouts since we're detached
121→	// Read API key and endpoint from package-level vars (not passed via argv for security)
122→	client, err := posthog.NewWithConfig(PostHogAPIKey, posthog.Config{
123→		Endpoint:     PostHogEndpoint,
124→		Logger:       silentLogger{},
125→		DisableGeoIP: posthog.Ptr(true),
126→	})
127→	if err != nil {
128→		return
129→	}
130→	defer func() {
131→		_ = client.Close()
132→	}()
133→
134→	// Build properties
135→	props := posthog.NewProperties()
136→	for k, v := range payload.Properties {
137→		props.Set(k, v)
138→	}
139→
140→	//nolint:errcheck // Best effort telemetry - don't block on result
141→	_ = client.Enqueue(posthog.Capture{
142→		DistinctId: payload.DistinctID,
143→		Event:      payload.Event,
144→		Properties: props,
145→		Timestamp:  payload.Timestamp,
146→	})
147→}
