 67→// globalConfigDirPath returns the expanded path to the global config directory (~/.config/entire).
 68→func globalConfigDirPath() (string, error) {
 69→	home, err := os.UserHomeDir()
 70→	if err != nil {
 71→		return "", fmt.Errorf("getting home directory: %w", err)
 72→	}
 73→	return filepath.Join(home, globalConfigDirName), nil
 74→}
 75→
 76→// ensureGlobalConfigDir creates the global config directory if it doesn't exist.
 77→func ensureGlobalConfigDir() error {
 78→	configDir, err := globalConfigDirPath()
 79→	if err != nil {
 80→		return err
 81→	}
 82→
 83→	//nolint:gosec // ~/.config/entire is user home directory, 0o755 is appropriate
 84→	if err := os.MkdirAll(configDir, 0o755); err != nil {
 85→		return fmt.Errorf("creating config directory: %w", err)
 86→	}
 87→
 88→	return nil
 89→}
 90→
 91→// cacheFilePath returns the full path to the version check cache file.
 92→func cacheFilePath() (string, error) {
 93→	configDir, err := globalConfigDirPath()
 94→	if err != nil {
 95→		return "", err
 96→	}
 97→	return filepath.Join(configDir, cacheFileName), nil
 98→}
 99→
100→// loadCache loads the version check cache from disk.
101→// Returns an error if the file doesn't exist or is corrupted.
102→func loadCache() (*VersionCache, error) {
103→	filePath, err := cacheFilePath()
104→	if err != nil {
105→		return nil, err
106→	}
107→
108→	data, err := os.ReadFile(filePath) //nolint:gosec // cacheFilePath is safe
109→	if err != nil {
110→		return nil, fmt.Errorf("reading cache file: %w", err)
111→	}
112→
113→	var cache VersionCache
114→	if err := json.Unmarshal(data, &cache); err != nil {
115→		return nil, fmt.Errorf("parsing cache: %w", err)
116→	}
117→
118→	return &cache, nil
119→}
120→
121→// saveCache saves the version check cache to disk.
122→// Uses atomic write semantics (write to temp file, then rename).
123→func saveCache(cache *VersionCache) error {
124→	filePath, err := cacheFilePath()
125→	if err != nil {
126→		return err
127→	}
128→
129→	// Marshal to JSON
130→	data, err := json.MarshalIndent(cache, "", "  ")
131→	if err != nil {
132→		return fmt.Errorf("marshaling cache: %w", err)
133→	}
134→
135→	// Write to temp file first (atomic write)
136→	dir := filepath.Dir(filePath)
137→	tmpFile, err := os.CreateTemp(dir, ".version_check_tmp_")
138→	if err != nil {
139→		return fmt.Errorf("creating temp file: %w", err)
140→	}
141→	defer os.Remove(tmpFile.Name())
142→
143→	if _, err := tmpFile.Write(data); err != nil {
144→		_ = tmpFile.Close() // cleanup on error path
145→		return fmt.Errorf("writing cache: %w", err)
146→	}
147→
148→	if err := tmpFile.Close(); err != nil {
149→		return fmt.Errorf("closing temp file: %w", err)
150→	}

150→	}
151→
152→	// Rename temp file to final location
153→
154→	if err := os.Rename(tmpFile.Name(), filePath); err != nil {
155→		return fmt.Errorf("renaming cache file: %w", err)
156→	}
157→
158→	return nil
159→}
160→
161→// fetchLatestVersion fetches the latest version from the GitHub API.
162→// Returns a timeout-safe version check using the configured HTTP timeout.
163→func fetchLatestVersion(ctx context.Context) (string, error) {
164→	// Create a context with timeout for the HTTP request
165→	ctx, cancel := context.WithTimeout(ctx, httpTimeout)
166→	defer cancel()
167→
168→	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
169→	if err != nil {
170→		return "", fmt.Errorf("creating request: %w", err)
171→	}
172→
173→	// Set headers to identify as Entire CLI
174→	req.Header.Set("Accept", "application/vnd.github+json")
175→	req.Header.Set("User-Agent", "entire-cli")
176→
177→	client := &http.Client{}
178→	resp, err := client.Do(req)
179→	if err != nil {
180→		return "", fmt.Errorf("fetching release info: %w", err)
181→	}
182→	defer resp.Body.Close()
183→
184→	if resp.StatusCode != http.StatusOK {
185→		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
186→	}
187→
188→	// Read response body (limit to 1MB to prevent memory exhaustion)
189→	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
190→	if err != nil {
191→		return "", fmt.Errorf("reading response: %w", err)
192→	}
193→
194→	// Parse GitHub release response
195→	version, err := parseGitHubRelease(body)
196→	if err != nil {
197→		return "", fmt.Errorf("parsing release: %w", err)
198→	}
199→
200→	return version, nil
201→}
202→
203→// parseGitHubRelease parses the GitHub API response and extracts the latest stable version.
204→// Filters out prerelease versions.
205→func parseGitHubRelease(body []byte) (string, error) {
206→	var release GitHubRelease
207→	if err := json.Unmarshal(body, &release); err != nil {
208→		return "", fmt.Errorf("parsing JSON: %w", err)
209→	}
210→
211→	// Skip prerelease versions
212→	if release.Prerelease {
213→		return "", errors.New("only prerelease versions available")
214→	}
215→
216→	// Ensure we have a tag name
217→	if release.TagName == "" {
218→		return "", errors.New("empty tag name")
219→	}
220→
221→	return release.TagName, nil
222→}
223→
224→// isOutdated compares current and latest versions using semantic versioning.
225→// Returns true if current < latest.
226→func isOutdated(current, latest string) bool {
227→	// Ensure versions have "v" prefix for semver package
228→	if !strings.HasPrefix(current, "v") {
229→		current = "v" + current
230→	}
231→	if !strings.HasPrefix(latest, "v") {
232→		latest = "v" + latest
233→	}
234→
235→	// Skip notification for dev builds (e.g., "1.0.0-dev-xxx").
236→	// These are local development builds and shouldn't trigger update notifications.
237→	// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
238→	if strings.Contains(semver.Prerelease(current), "dev") {
239→		return false
240→	}
241→
242→	// semver.Compare returns -1 if current < latest
243→	return semver.Compare(current, latest) < 0
244→}
245→
246→// executablePath is the function used to get the current executable path.
247→// It's a variable so tests can override it.
248→var executablePath = os.Executable
