```go
package llmcli

// Runner executes prompts via the Claude CLI.
type Runner struct {
    // ClaudePath is the path to the claude CLI executable.
    // If empty, defaults to "claude".
    ClaudePath string

    // Model is the Claude model to use.
    // If empty, defaults to DefaultModel ("sonnet").
    Model string

    // CommandRunner allows injection of the command execution for testing.
    // If nil, uses exec.CommandContext directly.
    CommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd
}

const DefaultModel = "sonnet"

// Execute runs a prompt through the Claude CLI and returns the raw text result.
// It handles:
// - CLI invocation with --print --output-format json --model --setting-sources ""
// - Git isolation (TempDir cwd, strip GIT_* env vars)
// - Response parsing ({"result": "string"} format)
// - Markdown code block extraction
func (r *Runner) Execute(ctx context.Context, prompt string) (string, error)

// StripGitEnv returns a copy of env with all GIT_* variables removed.
func StripGitEnv(env []string) []string

// ExtractJSONFromMarkdown attempts to extract JSON from markdown code blocks.
func ExtractJSONFromMarkdown(s string) string
```

**Then refactor `cmd/entire/cli/summarize/claude.go`** to use llmcli:
- `ClaudeGenerator` keeps its struct but internally creates an `llmcli.Runner` and calls `Execute()`
- The summarization prompt template stays in summarize
- Remove `stripGitEnv` and `extractJSONFromMarkdown` from summarize (now in llmcli)
- The `claudeCLIResponse` type moves to llmcli (or is internal to Execute)
- The `Generate()` method: builds prompt → calls `runner.Execute(ctx, prompt)` → parses JSON into `checkpoint.Summary`

**EXISTING summarize/claude.go** (the source to extract from):
```go
package summarize

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
)

const summarizationPromptTemplate = `Analyze this development session transcript...`
const DefaultModel = "sonnet"

type ClaudeGenerator struct {
	ClaudePath    string
	Model         string
	CommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd
}

type claudeCLIResponse struct {
	Result string `json:"result"`
}

func (g *ClaudeGenerator) Generate(ctx context.Context, input Input) (*checkpoint.Summary, error) {
	transcriptText := FormatCondensedTranscript(input)
	prompt := buildSummarizationPrompt(transcriptText)

	runner := g.CommandRunner
	if runner == nil { runner = exec.CommandContext }
	claudePath := g.ClaudePath
	if claudePath == "" { claudePath = "claude" }
	model := g.Model
	if model == "" { model = DefaultModel }

	cmd := runner(ctx, claudePath, "--print", "--output-format", "json", "--model", model, "--setting-sources", "")
	cmd.Dir = os.TempDir()
	cmd.Env = stripGitEnv(os.Environ())
	cmd.Stdin = strings.NewReader(prompt)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	if err != nil {
		var execErr *exec.Error
		if errors.As(err, &execErr) {
			return nil, fmt.Errorf("claude CLI not found: %w", err)
		}
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return nil, fmt.Errorf("claude CLI failed (exit %d): %s", exitErr.ExitCode(), stderr.String())
		}
		return nil, fmt.Errorf("failed to run claude CLI: %w", err)
	}

	var cliResponse claudeCLIResponse
	if err := json.Unmarshal(stdout.Bytes(), &cliResponse); err != nil {
		return nil, fmt.Errorf("failed to parse claude CLI response: %w", err)
	}

	resultJSON := cliResponse.Result
	resultJSON = extractJSONFromMarkdown(resultJSON)

	var summary checkpoint.Summary
	if err := json.Unmarshal([]byte(resultJSON), &summary); err != nil {
		return nil, fmt.Errorf("failed to parse summary JSON: %w (response: %s)", err, resultJSON)
	}

	return &summary, nil
}

func buildSummarizationPrompt(transcriptText string) string {
	return fmt.Sprintf(summarizationPromptTemplate, transcriptText)
}

func stripGitEnv(env []string) []string {
	filtered := make([]string, 0, len(env))
	for _, e := range env {
		if !strings.HasPrefix(e, "GIT_") { filtered = append(filtered, e) }
	}
	return filtered
}

func extractJSONFromMarkdown(s string) string {
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "` `` json") {
		s = strings.TrimPrefix(s, "` `` json")
		if idx := strings.LastIndex(s, "` ``"); idx != -1 { s = s[:idx] }
		return strings.TrimSpace(s)
	}
	if strings.HasPrefix(s, "` ``") {
		s = strings.TrimPrefix(s, "` ``")
		if idx := strings.LastIndex(s, "` ``"); idx != -1 { s = s[:idx] }
		return strings.TrimSpace(s)
	}
	return s
}
```

**Important constraints:**
- Go module path: `github.com/entireio/cli`
- `summarize.DefaultModel` constant should be removed and callers should use `llmcli.DefaultModel` instead. But if summarize tests reference it, you can keep a `const DefaultModel = llmcli.DefaultModel` alias.
- The summarize tests in `cmd/entire/cli/summarize/claude_test.go` and `cmd/entire/cli/summarize/summarize_test.go` must still pass after refactoring. The tests inject `CommandRunner` for mocking — make sure `llmcli.Runner.CommandRunner` has the same signature.
- Write tests for the llmcli package (StripGitEnv, ExtractJSONFromMarkdown, Execute with mock CommandRunner)
- Use TDD: write tests first, then implement
- Run `go test ./cmd/entire/cli/summarize/... ./cmd/entire/cli/llmcli/...` to verify
- Run `go build ./cmd/entire/...` to verify full build
- Commit when done: "refactor: extract shared Claude CLI execution to llmcli package"

